{
  "version": 1,
  "defaultSuite": "smoke",
  "suites": {
    "smoke": [
      {
        "action": "assert",
        "expr": "['audioTab_forYou', 'audioTab_search', 'audioTab_player', 'audioTab_queue', 'audioTab_albums'].every(id => !!document.querySelector('[aria-label=\"' + id + '\"]'))",
        "matcher": "truthy"
      },
      {
        "action": "eval",
        "expr": "(() => { const b = document.querySelector('[aria-label=\"audioTab_queue\"]'); if (!b) throw new Error('queue tab missing'); b.click(); return 'ok' })()"
      },
      { "action": "wait", "ms": 800 },
      {
        "action": "assert",
        "expr": "document.body.innerText.includes('队列')",
        "matcher": "truthy"
      },
      {
        "action": "eval",
        "expr": "(() => { const b = document.querySelector('[aria-label=\"audioTab_player\"]'); if (!b) throw new Error('player tab missing'); b.click(); return 'ok' })()"
      },
      { "action": "wait", "ms": 800 },
      {
        "action": "assert",
        "expr": "!/undefined|NaN|\\[object Object\\]/.test(document.body.innerText)",
        "matcher": "truthy"
      },
      { "action": "assert", "matcher": "noHorizontalOverflow" }
    ],
    "engine": [
      {
        "action": "assert",
        "expr": "!!(window.aibox && window.aibox.music && typeof window.aibox.music.search === 'function')",
        "matcher": "truthy"
      },
      {
        "action": "eval",
        "expr": "(() => { window.__aiboxMusicProbe = 'pending'; window.aibox.music.search({ query: 'jazz', limit: 5 }).then(r => { window.__aiboxMusicProbe = JSON.stringify(r).slice(0, 400) }).catch(e => { window.__aiboxMusicProbe = 'ERR ' + (e && e.message ? e.message : e) }); return 'sent' })()"
      },
      { "action": "wait", "ms": 4000 },
      {
        "action": "assert",
        "expr": "window.__aiboxMusicProbe",
        "matcher": "contains",
        "expected": "\"ok\":true"
      },
      {
        "action": "eval",
        "expr": "(() => { const b = document.querySelector('[aria-label=\"audioTab_forYou\"]'); if (!b) throw new Error('forYou tab missing'); b.click(); return 'ok' })()"
      },
      { "action": "wait", "ms": 3000 },
      {
        "action": "assert",
        "expr": "document.body.innerText.replace(/\\s+/g, '').length > 60",
        "matcher": "truthy"
      }
    ]
  }
}

// 音乐（com.aibox.music）—— AiBoxMusicKit 的 React 复刻。
//
// 根职责：装配 store / MusicController → 接宿主外壳（tabs / toolbar / navigation / 动作注册）
// → 路由子页 → 渲染当前 Tab + mini 播放条。
//
// ⚠️ 架构裁决：**遥控宿主播放引擎 `aibox.music.*`，绝不用 `aibox.media` 自持引擎**。
// 播放、锁屏 NowPlaying、remote command、后台续播、中断恢复全部留在原生侧；
// 播放队列同理留在原生（`music_queue`），本应用不维护影子队列。
// 依据：docs/capabilities/applet/framework-capabilities.md §3.6 / §3.6.1。

import React from 'react'
import { THEME_CSS } from './components/theme.js'
import { Header, Notice, TabBar } from './components/Shell.jsx'
import NowPlaying from './components/NowPlaying.jsx'
import MiniBar from './components/MiniBar.jsx'
import QueuePage from './components/QueuePage.jsx'
import ForYouPage from './components/ForYouPage.jsx'
import SearchPage from './components/SearchPage.jsx'
import LibraryPage from './components/LibraryPage.jsx'
import LocalLibrary from './components/LocalLibrary.jsx'
import SettingsPage from './components/SettingsPage.jsx'
import EffectsPage from './components/EffectsPage.jsx'
import OptionsMenu, { OptionPicker } from './components/OptionsMenu.jsx'
import { CollectionDetail, CategoryList } from './components/DetailPage.jsx'
import { FavoritesSheet, HistorySheet } from './components/Sheets.jsx'
import { MusicStore } from './lib/store.js'
import { MusicController } from './lib/music.js'
import { fetchLyrics } from './lib/lyrics.js'
import { backfillArtworkURL, artworkDataURL, dominantColor, sizedArtworkURL } from './lib/artwork.js'
import { playArgs, stableKey } from './lib/format.js'
import {
  actionSheet, confirm, haptics, music as callMusic, openURL,
  onEvent, onNamespaceEvent, registerAction, setNavigationTitle, shareText, tabs, toolbar,
} from './lib/host.js'
import { ACTION_HANDLERS } from './lib/actions.js'
import { useSubpageStack } from './lib/subpages.js'
import { currentLocale, makeT, onLocaleChanged } from './i18n/index.js'

const TABS = [
  { id: 'forYou', titleKey: 'tab.forYou', icon: 'sparkles' },
  { id: 'search', titleKey: 'tab.search', icon: 'magnifyingglass' },
  { id: 'player', titleKey: 'tab.player', icon: 'play.circle' },
  { id: 'queue', titleKey: 'tab.queue', icon: 'list.bullet' },
  { id: 'albums', titleKey: 'tab.albums', icon: 'square.stack' },
]

function useThemeSetup() {
  React.useEffect(() => {
    if (document.getElementById('__music_css__')) return
    const style = document.createElement('style')
    style.id = '__music_css__'
    style.textContent = THEME_CSS
    document.head.appendChild(style)
  }, [])
  React.useEffect(() => {
    const query = window.matchMedia ? window.matchMedia('(prefers-color-scheme: dark)') : null
    const apply = () => {
      document.documentElement.setAttribute('data-prefers-color-scheme', query && query.matches ? 'dark' : 'light')
    }
    apply()
    if (query && query.addEventListener) {
      query.addEventListener('change', apply)
      return () => query.removeEventListener('change', apply)
    }
    return undefined
  }, [])
}

export default function App() {
  useThemeSetup()
  const [, forceRender] = React.useReducer((n) => n + 1, 0)

  const [locale, setLocale] = React.useState(currentLocale)
  const t = React.useMemo(() => makeT(locale), [locale])
  // 子页标题在 push 那一刻要用最新的翻译函数，而 push 回调是稳定的 —— 经 ref 取值。
  const tRef = React.useRef(t)
  tRef.current = t

  const refs = React.useRef(null)
  if (refs.current === null) {
    const store = new MusicStore()
    refs.current = { store, music: new MusicController({ store }) }
  }
  const { store, music } = refs.current

  const [tab, setTab] = React.useState('player')
  // 子页栈 = 宿主原生页栈的镜像（见 lib/subpages.js）：进详情走 `aibox.navigation.push`，
  // 返回一律经 popstate 回来，于是最左缘左滑是**系统自己的** interactive pop。
  const subpages = useSubpageStack({
    pathFor: routePath,
    titleFor: (row) => routeTitle(row, tRef.current),
  })
  const { stack } = subpages
  const [sheet, setSheet] = React.useState(null)
  const [menuOpen, setMenuOpen] = React.useState(false)
  const [picker, setPicker] = React.useState(null)
  const [query, setQuery] = React.useState('')
  const [shell, setShell] = React.useState({ tabsRendered: false, toolbarRendered: false, searchRendered: false })
  const [mode, setMode] = React.useState('album')
  const [lyrics, setLyrics] = React.useState({ state: 'none', synced: false, lines: [] })
  const [artwork, setArtwork] = React.useState({ url: null, color: null })
  const [favorites, setFavorites] = React.useState({ loading: true, rows: [] })
  const [notice, setNotice] = React.useState(null)

  // —— 订阅两个模型 ——
  React.useEffect(() => {
    const offs = [store.subscribe(forceRender), music.subscribe(forceRender)]
    return () => offs.forEach((off) => off())
  }, [store, music])

  React.useEffect(() => onLocaleChanged(setLocale), [])

  // —— 启动 ——
  React.useEffect(() => {
    let cancelled = false
    const boot = async () => {
      await store.load()
      if (cancelled) return
      setTab(store.ui.selectedTab || 'player')
      music.start()
      music.refreshSleepTimer()
      music.refreshEffects()
    }
    boot()
    return () => { cancelled = true; music.stop() }
  }, [store, music])

  // —— 页面不可见时停轮询（锁屏/后台的媒体 UI 是原生那一面，与本页无关）——
  React.useEffect(() => {
    const apply = () => music.setVisible(!document.hidden)
    document.addEventListener('visibilitychange', apply)
    const off = onEvent('lifecycle.background', () => { store.flushNow(); music.setVisible(false) })
    const offForeground = onEvent('lifecycle.foreground', () => music.setVisible(true))
    return () => {
      document.removeEventListener('visibilitychange', apply)
      if (off) off()
      if (offForeground) offForeground()
    }
  }, [music, store])

  // —— 10Hz 插值 tick：只在播放页可见且真的在走时才跑 ——
  const playing = music.status.isPlaying
  React.useEffect(() => {
    if (tab !== 'player' && !showMiniFor(tab, music.currentTrack)) return undefined
    if (stack.length > 0) return undefined
    if (!playing) return undefined
    const timer = setInterval(forceRender, 100)
    return () => clearInterval(timer)
  }, [tab, stack.length, playing, music])

  // —— 对外动作（AI / 自动化）——
  React.useEffect(() => {
    Object.keys(ACTION_HANDLERS).forEach((name) => registerAction(name, ACTION_HANDLERS[name]))
  }, [])

  // 外壳接线只跑一次，而 reset 要在每次切 Tab 时清掉子页栈 —— 经 ref 取最新那一个。
  const resetRef = React.useRef(subpages.reset)
  resetRef.current = subpages.reset

  // —— 宿主外壳接线 ——
  React.useEffect(() => {
    let cancelled = false
    const offs = []
    const wire = async () => {
      const state = await tabs.getState()
      if (!cancelled && state && state.rendered) {
        setShell((current) => ({ ...current, tabsRendered: true }))
        // 默认落在 Now Playing（5 个 tab 的正中间），不是资料库。
        tabs.select(store.ui.selectedTab || 'player')
      }
      offs.push(onNamespaceEvent('tabs', 'changed', (payload) => {
        if (!payload) return
        // `rendered` 会**在挂载之后翻转**（形态切换、控制器重建都会重发 changed）。
        // 只在启动那一刻判断一次，自绘 TabBar 就会永远缺席或永远多一条。
        const rendered = payload.rendered !== false
        setShell((current) => (current.tabsRendered === rendered
          ? current : { ...current, tabsRendered: rendered }))
        if (payload.selected) {
          haptics.selection()
          setTab(payload.selected)
          resetRef.current()
          setMode('album')
        }
      }))
      const bar = await toolbar.getState()
      if (!cancelled && bar) {
        setShell((current) => ({
          ...current,
          toolbarRendered: bar.rendered !== false,
          searchRendered: !!(bar.search && bar.search.rendered),
        }))
      }
      // `more` 在 manifest 里是 `role:"hostMenu"` 的**位置标记**、不是按钮：它不渲染、
      // 也永不发 `toolbar.invoke`。菜单内容改由 `scene.menu` 声明，宿主用原生 Menu 画。
      // 自绘 ⋯（没有宿主顶栏的形态）仍走 OptionsMenu，见下面的 Header。
      offs.push(onNamespaceEvent('toolbar', 'searchChanged', (payload) => {
        setQuery(String((payload && payload.query) || ''))
      }))
    }
    wire()
    return () => { cancelled = true; offs.forEach((off) => off && off()) }
  }, [store])

  // —— 顶栏标题 ——
  React.useEffect(() => {
    const route = stack[stack.length - 1]
    const title = route ? routeTitle(route, t) : tabTitle(tab, music.status.queueCount, t)
    document.title = title || t('common.music')
    setNavigationTitle(title)
  }, [tab, stack, music.status.queueCount, t])

  React.useEffect(() => { store.setSelectedTab(tab) }, [tab, store])

  // —— 当前曲变化：封面 → 主色 → 歌词 ——
  const trackKey = music.trackKey
  const current = music.currentTrack
  React.useEffect(() => {
    let cancelled = false
    setArtwork({ url: store.artworkURL(current), color: null })
    if (!current) { setLyrics({ state: 'none', synced: false, lines: [] }); return undefined }
    const run = async () => {
      let url = store.artworkURL(current)
      if (!url) url = await backfillArtworkURL(current, { store, music: callMusic })
      if (cancelled || !url) return
      setArtwork((state) => ({ ...state, url }))
      const data = await artworkDataURL(sizedArtworkURL(url, 200))
      if (cancelled || !data) return
      const color = await dominantColor(data)
      if (!cancelled) setArtwork((state) => ({ ...state, color }))
    }
    run()
    return () => { cancelled = true }
  }, [trackKey]) // eslint-disable-line react-hooks/exhaustive-deps

  // —— 歌词：**可见性门** —— 歌词面不可见时不取词，避免一打开播放器就急着拉网络。
  React.useEffect(() => {
    if (!current || mode !== 'lyrics' || tab !== 'player') return undefined
    let cancelled = false
    setLyrics({ state: 'loading', synced: false, lines: [] })
    fetchLyrics(callMusic, current).then((payload) => { if (!cancelled) setLyrics(payload) })
    return () => { cancelled = true }
  }, [trackKey, mode, tab]) // eslint-disable-line react-hooks/exhaustive-deps

  // —— 收藏列表 ——
  const refreshFavorites = React.useCallback(async () => {
    const result = await callMusic('library', { action: 'list_favorites' })
    const rows = Array.isArray(result.json) ? result.json : []
    rows.forEach((row) => store.rememberArtwork(row))
    setFavorites({ loading: false, rows })
  }, [store])
  React.useEffect(() => { refreshFavorites() }, [refreshFavorites])

  const showNotice = React.useCallback((message) => {
    setNotice(message)
    setTimeout(() => setNotice(null), 2600)
  }, [])

  const { push: navigate, back } = subpages

  const selectTab = React.useCallback((next) => {
    haptics.selection()
    setTab(next)
    resetRef.current()
    setMode('album')
    tabs.select(next)
  }, [])

  const favoriteKeys = React.useMemo(
    () => new Set(favorites.rows.map((row) => stableKey(row)).filter(Boolean)),
    [favorites.rows],
  )

  const toggleFavorite = React.useCallback(async (track, next) => {
    if (!track) return
    const key = stableKey(track)
    const on = next === undefined ? !favoriteKeys.has(key) : next
    haptics.impact('light')
    await callMusic('library', { action: on ? 'favorite' : 'unfavorite', ...playArgs(track) })
    refreshFavorites()
  }, [favoriteKeys, refreshFavorites])

  const actions = React.useMemo(() => ({
    navigate,
    back,
    notice: showNotice,
    openSheet: setSheet,
    pickOption: setPicker,
    playTrack: (track, group) => music.play(track, group),
    playQueueIndex: (index) => {
      const track = music.queue.tracks[index]
      if (track) music.play(track, music.queue.tracks)
    },
    addToQueue: (track) => music.addToQueue(track),
    removeQueue: (index) => music.removeFromQueue(index),
    moveQueue: (from, to) => music.moveInQueue(from, to),
    shufflePlay: async (tracks) => {
      // 「随机」= 先开启随机模式，再从第一首起播（与原生同序）。
      await music.setShuffle(true)
      if (tracks && tracks.length > 0) music.play(tracks[0], tracks)
    },
    openCollection: (item) => {
      store.rememberArtwork(item)
      navigate({ name: 'collection', item })
    },
    playCollection: async (item) => {
      const result = await callMusic('album', { action: 'play', id: item.musicItemId })
      if (!result.ok) showNotice(result.error || t('err.generic'))
      music.refreshStatus()
    },
    toggleFavorite,
    shareCurrent: async () => {
      const track = music.currentTrack
      if (!track) return
      const link = store.externalURL(track)
      await shareText([track.title, track.artist].filter(Boolean).join(' — '), link || undefined)
    },
    confirmClear: async (message, run) => {
      const ok = await confirm({
        title: message,
        confirmTitle: t('common.clear'),
        cancelTitle: t('common.cancel'),
        destructive: true,
      })
      if (ok) run()
    },
    confirmDestructive: async ({ title, message, confirmTitle, onConfirm }) => {
      const ok = await confirm({ title, message, confirmTitle, cancelTitle: t('common.cancel'), destructive: true })
      if (ok) onConfirm()
    },
    trackMenu: async (track, options = {}) => {
      const key = stableKey(track)
      const isFavorite = favoriteKeys.has(key)
      const link = store.externalURL(track)
      const picked = await actionSheet({
        title: track.title,
        actions: [
          { id: 'play', title: t('common.play') },
          { id: 'queue', title: t('common.addToQueue') },
          { id: 'favorite', title: isFavorite ? t('common.removeFromFavorites') : t('common.addToFavorites') },
          ...(link ? [{ id: 'open', title: t('common.openInAppleMusic') }] : []),
          ...(options.queueIndex !== undefined
            ? [{ id: 'remove', title: t('common.remove'), role: 'destructive' }] : []),
          { id: 'cancel', title: t('common.cancel'), role: 'cancel' },
        ],
      })
      if (picked === 'play') music.play(track, options.group)
      else if (picked === 'queue') music.addToQueue(track)
      else if (picked === 'favorite') toggleFavorite(track, !isFavorite)
      else if (picked === 'open' && link) openURL(link)
      else if (picked === 'remove') music.removeFromQueue(options.queueIndex)
    },
    collectionMenu: async (item) => {
      const picked = await actionSheet({
        title: item.title || item.name,
        actions: [
          { id: 'play', title: t('common.play') },
          ...(item.url ? [{ id: 'open', title: t('common.openInAppleMusic') }] : []),
          { id: 'cancel', title: t('common.cancel'), role: 'cancel' },
        ],
      })
      if (picked === 'play') {
        const result = await callMusic('album', { action: 'play', id: item.musicItemId })
        if (!result.ok) showNotice(result.error || t('err.generic'))
      } else if (picked === 'open' && item.url) openURL(item.url)
    },
  }), [music, store, navigate, back, showNotice, t, toggleFavorite, favoriteKeys])

  const ctx = React.useMemo(() => ({
    t,
    locale,
    store,
    music,
    actions,
    favorites: favorites.rows,
    favoritesLoading: favorites.loading,
    externalURL: current ? store.externalURL(current) : null,
    version: music.version + store.version,
  }), [t, locale, store, music, actions, favorites, current, music.version, store.version]) // eslint-disable-line react-hooks/exhaustive-deps

  const { route } = subpages
  const showMini = showMiniFor(tab, current) && !route

  // —— 宿主 ⋯ 菜单（scene.menu）——
  //
  // 这些行以前是自绘面板（web 菜单），于是顶栏出现**两个 ⋯**：`more` 没标 `role:"hostMenu"`，
  // 宿主把它当普通按钮画在前面、再画自己的 ⋯。现在菜单内容整体迁进 `scene.menu`，
  // `more` 退化成位置标记，右上角只剩一个 ⋯，而且是系统原生 Menu。
  //
  // 每轮重注册：处理器要闭包到最新的 music / navigate / actions。
  React.useEffect(() => {
    registerAction('toggleShuffle', () => { music.setShuffle(!music.status.isShuffled); return null })
    registerAction('setRepeat', (mode) => { music.setRepeat(String(mode || 'off')); return null })
    registerAction('setSleepTimer', (input) => {
      const value = input || {}
      if (value.mode === 'off') music.cancelSleepTimer()
      else if (value.mode === 'endOfTrack') music.setSleepTimerEndOfTrack()
      else music.setSleepTimer(Math.max(1, Number(value.minutes) || 0))
      return null
    })
    registerAction('openEffects', () => { navigate({ name: 'effects' }); return null })
    registerAction('openSettings', () => { navigate({ name: 'settings' }); return null })
    registerAction('shareCurrent', () => { actions.shareCurrent(); return null })
  })

  // 原生菜单项没有「勾选态」「右侧详情」两个字段，只能覆盖 title / icon / enabled / hidden。
  // 所以：勾选用 `icon: 'checkmark'` 表达（就是系统菜单的写法），当前值并进标题。
  const menuStatus = music.status
  const sleepTimer = music.sleepTimer
  const externalURL = current ? store.externalURL(current) : null
  React.useEffect(() => {
    const api = window.aibox
    if (!api || !api.menu || typeof api.menu.update !== 'function') return
    // 播放相关的几项只在「正在播放」页出现（照抄原生 AiBoxMusicKit 的 ⋯ 菜单）。
    const isPlayer = tab === 'player' && !route
    const repeatValue = {
      off: t('menu.repeatOff'), one: t('menu.repeatOne'), all: t('menu.repeatAll'),
    }[menuStatus.repeatMode] || t('menu.repeatOff')
    const timerValue = sleepTimer.endOfTrack
      ? t('menu.stopAfterSong')
      : (sleepTimer.remaining !== null && sleepTimer.remaining !== undefined
        ? t('menu.stopIn', `${Math.floor(sleepTimer.remaining / 60)}:${String(sleepTimer.remaining % 60).padStart(2, '0')}`)
        : t('menu.notSet'))
    api.menu.update({
      items: {
        shuffle: { hidden: !isPlayer, icon: menuStatus.isShuffled ? 'checkmark' : 'shuffle' },
        repeat: {
          hidden: !isPlayer,
          icon: menuStatus.repeatMode === 'one' ? 'repeat.1' : 'repeat',
          title: `${t('menu.repeat')} · ${repeatValue}`,
        },
        repeatOff: { icon: menuStatus.repeatMode === 'off' ? 'checkmark' : null },
        repeatOne: { icon: menuStatus.repeatMode === 'one' ? 'checkmark' : null },
        repeatAll: { icon: menuStatus.repeatMode === 'all' ? 'checkmark' : null },
        sleepTimer: { hidden: !isPlayer, title: `${t('menu.sleepTimer')} · ${timerValue}` },
        sleepOff: { hidden: !sleepTimer.active },
        audioEffects: { hidden: !isPlayer },
        shareTrack: { hidden: !isPlayer || !externalURL },
      },
    }).catch(() => {})
  }, [tab, route, t, externalURL, menuStatus.isShuffled, menuStatus.repeatMode,
    sleepTimer.active, sleepTimer.endOfTrack, sleepTimer.remaining])

  return (
    <div className="mu-root">
      {/* 宿主画了顶栏就**不再自绘** —— 子页也不自绘：宿主在 `webDepth > 0` 时自己就有返回键，
          ⋯ 也由宿主的原生 Menu 画。没有宿主顶栏时（fullscreen 形态 / 无宿主）才补上这一条。 */}
      {!shell.toolbarRendered ? (
        <Header
          title={route ? routeTitle(route, t) : tabTitle(tab, music.status.queueCount, t)}
          onBack={route ? back : undefined}
          onMenu={route ? undefined : () => setMenuOpen(true)}
          transparent={!route && tab === 'player'}
        />
      ) : null}

      {route ? renderRoute(route, ctx) : (
        <>
          {tab === 'player' ? (
            <NowPlaying
              track={current}
              status={music.status}
              busy={music.isBusy}
              progress={music.displayProgress()}
              position={music.displayTime()}
              duration={music.status.duration}
              artworkURL={artwork.url}
              color={artwork.color}
              lyrics={lyrics}
              mode={mode}
              onSetMode={(next) => { haptics.selection(); setMode(next) }}
              isFavorite={favoriteKeys.has(stableKey(current))}
              onToggleFavorite={() => toggleFavorite(current)}
              onOpenTrackMenu={() => current && actions.trackMenu(current)}
              scrub={{
                begin: (ratio) => music.beginScrub(ratio),
                update: (ratio) => music.updateScrub(ratio),
                end: () => music.endScrub(),
              }}
              onPrevious={() => music.transport('previous')}
              onNext={() => music.transport('next')}
              onTogglePlay={() => music.togglePlayPause()}
              onSeekSeconds={(seconds) => music.seekTo(seconds)}
              onRetry={() => music.retry()}
              t={t}
            />
          ) : null}
          {tab === 'forYou' ? <ForYouPage ctx={ctx} /> : null}
          {tab === 'search' ? (
            <SearchPage ctx={ctx} query={query} onQueryChange={setQuery} searchRendered={shell.searchRendered} />
          ) : null}
          {tab === 'queue' ? <QueuePage ctx={ctx} /> : null}
          {tab === 'albums' ? <LibraryPage ctx={ctx} /> : null}
        </>
      )}

      <Notice message={notice} />

      {showMini ? (
        <MiniBar
          track={{ ...current, artworkUrl: artwork.url }}
          isPlaying={music.status.isPlaying}
          busy={music.isBusy}
          progress={music.displayProgress()}
          onOpen={() => selectTab('player')}
          onToggle={() => music.togglePlayPause()}
          onNext={() => music.transport('next')}
          t={t}
        />
      ) : null}

      {!shell.tabsRendered ? (
        <TabBar items={TABS} selected={tab} onSelect={selectTab} t={t} />
      ) : (
        <div style={{ height: 'env(safe-area-inset-bottom)', flex: '0 0 auto' }} />
      )}

      <OptionsMenu open={menuOpen} onClose={() => setMenuOpen(false)} tab={tab} ctx={ctx} />
      <OptionPicker request={picker} onClose={() => setPicker(null)} />
      <FavoritesSheet open={sheet === 'favorites'} onClose={() => setSheet(null)} ctx={ctx} />
      <HistorySheet open={sheet === 'history'} onClose={() => setSheet(null)} ctx={ctx} />
    </div>
  )
}

/** mini 播放条**只在非 Now Playing tab** 出现，且必须有当前曲目。 */
function showMiniFor(tab, track) {
  return tab !== 'player' && !!track
}

function tabTitle(tab, queueCount, t) {
  if (tab === 'player') return ''
  if (tab === 'queue') return queueCount > 0 ? t('nav.queueCount', queueCount) : t('tab.queue')
  const row = TABS.find((item) => item.id === tab)
  return row ? t(row.titleKey) : ''
}

/** 子页在 history 里的路径。页面自己不读它，只为宿主诊断与 `navigation.getState().url` 可读。 */
function routePath(route) {
  if (!route) return '#/'
  if (route.name === 'collection') return `#/collection/${encodeURIComponent((route.item && route.item.musicItemId) || '')}`
  if (route.name === 'category') return `#/category/${encodeURIComponent(route.id || '')}`
  return `#/${route.name}`
}

function routeTitle(route, t) {
  if (!route) return ''
  switch (route.name) {
    case 'settings': return t('settings.title')
    case 'effects': return t('effects.title')
    case 'local': return t('local.title')
    case 'category': return route.title
    case 'collection': return route.item.title || route.item.name || ''
    default: return ''
  }
}

function renderRoute(route, ctx) {
  switch (route.name) {
    case 'settings': return <SettingsPage ctx={ctx} />
    case 'effects': return <EffectsPage ctx={ctx} />
    case 'local': return <LocalLibrary ctx={ctx} />
    case 'category': return <CategoryList ctx={ctx} route={route} />
    case 'collection': return <CollectionDetail ctx={ctx} item={route.item} />
    default: return null
  }
}

// 详情页：专辑 / 歌单（§2.11）、艺人（§2.12）、资料库分类全列表（§2.13）。
// 用滚动容器 + 惰性纵列，不用 List——多按钮行的点击容易被吞。

import React from 'react'
import Icon from './Icon.jsx'
import { Artwork, EmptyState, ListHeader, Spinner } from './primitives.jsx'
import { CollectionRow, Divider, NumberedTrackRow, SongRow } from './rows.jsx'
import { C, SPACE } from './theme.js'
import { music as callMusic, openURL, haptics } from '../lib/host.js'

export function CollectionDetail({ ctx, item }) {
  const { t, actions, store } = ctx
  const [state, setState] = React.useState({ loading: true, tracks: [], albums: [] })

  React.useEffect(() => {
    let cancelled = false
    const load = async () => {
      const kind = item.type === 'artist' ? 'artist' : (item.type === 'playlist' ? 'playlist' : 'album')
      const result = await callMusic('get', {
        id: item.musicItemId,
        kind,
        ...(item.source === 'local' ? { source: 'local' } : {}),
      })
      if (cancelled) return
      const payload = result.json || {}
      const tracks = Array.isArray(payload.tracks) ? payload.tracks : []
      const albums = Array.isArray(payload.albums) ? payload.albums : []
      albums.forEach((row) => store.rememberArtwork(row))
      setState({ loading: false, tracks, albums, failed: !result.ok })
    }
    load()
    return () => { cancelled = true }
  }, [item, store])

  const isArtist = item.type === 'artist'
  const tracks = state.tracks

  return (
    <div className="mu-scroll" aria-label="audioCollectionDetail">
      <div style={{
        display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 10,
        padding: `12px ${SPACE.s4}px ${SPACE.s4}px`,
      }}
      >
        <Artwork
          url={item.artworkUrl}
          size={isArtist ? 130 : 180}
          radius={isArtist ? 65 : 12}
          iconSize={isArtist ? 30 : 44}
          shadow={isArtist ? '0 6px 12px rgba(0,0,0,0.2)' : '0 8px 14px rgba(0,0,0,0.22)'}
        />
        <span style={{ fontSize: isArtist ? 20 : 18, fontWeight: 700, textAlign: 'center' }}>
          {item.title || item.name}
        </span>
        {!isArtist && item.artist ? (
          <span className="mu-clamp-1" style={{ fontSize: 14, color: C.muted }}>{item.artist}</span>
        ) : null}
        {item.url ? (
          <button type="button" className="mu-btn mu-press" onClick={() => openURL(item.url)}
            style={{ display: 'flex', alignItems: 'center', gap: 6, color: C.accent, fontSize: 13 }}
          >
            <Icon name="arrow.up.forward.app" size={14} color={C.accent} />
            {t('common.openInAppleMusic')}
          </button>
        ) : null}

        {!isArtist ? (
          <div style={{ display: 'flex', gap: 10, width: '100%', paddingTop: 4 }}>
            <HeaderButton
              icon="play.fill"
              label={t('detail.play')}
              disabled={state.loading || tracks.length === 0}
              onClick={() => actions.playTrack(tracks[0], tracks)}
            />
            <HeaderButton
              icon="shuffle"
              label={t('detail.shuffle')}
              disabled={state.loading || tracks.length === 0}
              onClick={() => actions.shufflePlay(tracks)}
            />
          </div>
        ) : null}
      </div>

      {state.loading ? (
        <div style={{ padding: 30, display: 'flex', justifyContent: 'center' }}><Spinner color={C.muted} /></div>
      ) : null}

      {!state.loading && tracks.length === 0 && state.albums.length === 0 ? (
        <EmptyState
          icon="music.note.list"
          title={isArtist ? t('detail.artistFailed') : t('detail.personalized')}
          top={20}
          action={item.url ? (
            <button type="button" className="mu-btn mu-press" onClick={() => openURL(item.url)}
              style={{
                marginTop: 6, padding: '8px 16px', borderRadius: 999, fontSize: 14, fontWeight: 600,
                background: `color-mix(in srgb, ${C.accent} 15%, transparent)`, color: C.accent,
              }}
            >
              {t('common.openInAppleMusic')}
            </button>
          ) : null}
        />
      ) : null}

      {tracks.length > 0 ? (
        <>
          <ListHeader>{isArtist ? t('detail.topSongs') : t('detail.trackCount', tracks.length)}</ListHeader>
          {(isArtist ? tracks.slice(0, 10) : tracks).map((track, index) => (
            <React.Fragment key={track.id || `${index}`}>
              <NumberedTrackRow
                index={index}
                track={track}
                numberWidth={isArtist ? 24 : 28}
                onClick={() => actions.playTrack(track, tracks)}
                onLongPress={() => actions.trackMenu(track, { group: tracks })}
              />
              {index < tracks.length - 1 ? <Divider inset={isArtist ? 52 : 56} /> : null}
            </React.Fragment>
          ))}
        </>
      ) : null}

      {state.albums.length > 0 ? (
        <>
          <ListHeader>{t('detail.albums')}</ListHeader>
          <div className="mu-hrow" style={{ display: 'flex', gap: 12, padding: `0 ${SPACE.s4}px` }}>
            {state.albums.map((album) => (
              <button
                key={album.musicItemId}
                type="button"
                className="mu-btn mu-press"
                onClick={() => { haptics.impact('light'); actions.playCollection(album) }}
                style={{ width: 130, flex: '0 0 auto', display: 'flex', flexDirection: 'column', gap: 6 }}
              >
                <Artwork url={album.artworkUrl} size={130} radius={10} iconSize={28} />
                <span className="mu-clamp-1" style={{ fontSize: 13, fontWeight: 500, width: 130, textAlign: 'left' }}>
                  {album.title}
                </span>
              </button>
            ))}
          </div>
        </>
      ) : null}

      <div style={{ height: 24 }} />
    </div>
  )
}

function HeaderButton({ icon, label, disabled, onClick }) {
  return (
    <button
      type="button"
      className="mu-btn mu-press"
      disabled={disabled}
      onClick={onClick}
      style={{
        flex: '1 1 0', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6,
        padding: '10px 0', borderRadius: 10, fontSize: 15, fontWeight: 600,
        background: `color-mix(in srgb, ${C.accent} 15%, transparent)`, color: C.accent,
        opacity: disabled ? 0.4 : 1,
      }}
    >
      <Icon name={icon} size={15} color={C.accent} />
      {label}
    </button>
  )
}

/** 资料库分类全列表（§2.13）：读会话缓存，不重新请求网络。 */
export function CategoryList({ ctx, route }) {
  const { actions } = ctx
  const items = route.items || []
  const isSongs = route.id === 'songs'
  return (
    <div className="mu-scroll">
      {items.map((item, index) => (isSongs ? (
        <SongRow
          key={item.musicItemId || index}
          track={item}
          onClick={() => actions.playTrack(item, items)}
          onLongPress={() => actions.trackMenu(item, { group: items })}
        />
      ) : (
        <CollectionRow
          key={item.musicItemId || index}
          item={item}
          onClick={() => actions.openCollection(item)}
          onLongPress={() => actions.collectionMenu(item)}
        />
      )))}
      <div style={{ height: 24 }} />
    </div>
  )
}

// 音效页（§2.16）。三段：开关 / 速度 / 均衡器。**改动即时应用**，没有「保存」按钮。
// 全部经 `music_effects`（宿主工具覆盖完整，这一页没有降级）。

import React from 'react'
import { Card, ListHeader, Row, Spinner } from './primitives.jsx'
import { Switch } from './SettingsPage.jsx'
import { C, SPACE } from './theme.js'
import { bandLabel, gainLabel, presetRateLabel, rateLabel } from '../lib/format.js'

const PRESETS = ['flat', 'bass', 'vocal', 'treble', 'rock', 'pop', 'jazz', 'classical']
const RATE_PRESETS = [0.75, 1, 1.25, 1.5, 2]

export default function EffectsPage({ ctx }) {
  const { t, music } = ctx
  const effects = music.effects

  React.useEffect(() => { music.refreshEffects() }, [music])

  if (!effects) {
    return <div style={{ padding: 60, display: 'flex', justifyContent: 'center' }}><Spinner color={C.muted} /></div>
  }

  const bands = Array.isArray(effects.bands) ? effects.bands : []
  const preset = String(effects.preset || 'flat')

  return (
    <div className="mu-scroll">
      <Card style={{ marginTop: SPACE.s4 }}>
        <Row
          title={t('effects.enabled')}
          accessory={(
            <Switch
              value={!!effects.enabled}
              onChange={(value) => music.updateEffects('enable', { enabled: value })}
            />
          )}
          last
        />
      </Card>
      <div style={{ padding: `6px ${SPACE.s5}px ${SPACE.s2}px`, fontSize: 12, color: C.muted, lineHeight: 1.45 }}>
        {t('effects.footer')}
        {effects.appliesToCurrentTrack === false ? ` ${t('effects.appleMusicNote')}` : ''}
      </div>

      <ListHeader>{t('effects.speed')}</ListHeader>
      <Card>
        <div style={{ padding: `12px ${SPACE.s4}px` }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', paddingBottom: 4 }}>
            <span style={{ fontSize: 16 }}>{t('effects.speed')}</span>
            <span className="mu-mono" style={{ fontSize: 15, color: C.muted }}>{rateLabel(effects.rate)}</span>
          </div>
          <input
            className="mu-slider"
            type="range"
            min="0.5"
            max="2"
            step="0.05"
            value={Number(effects.rate) || 1}
            onChange={(event) => music.updateEffects('set_rate', { rate: Number(event.target.value) })}
          />
          <div style={{ display: 'flex', gap: 6, paddingTop: 8 }}>
            {RATE_PRESETS.map((rate) => {
              const active = Math.abs(Number(effects.rate) - rate) < 0.001
              return (
                <button
                  key={rate}
                  type="button"
                  className="mu-btn mu-press"
                  onClick={() => music.updateEffects('set_rate', { rate })}
                  style={{
                    flex: '1 1 0', textAlign: 'center', padding: '6px 0', borderRadius: 999, fontSize: 13,
                    background: active
                      ? `color-mix(in srgb, ${C.accent} 18%, transparent)`
                      : `color-mix(in srgb, ${C.muted} 12%, transparent)`,
                    color: active ? C.accent : C.ink,
                  }}
                >
                  {presetRateLabel(rate)}
                </button>
              )
            })}
          </div>
        </div>
      </Card>

      <ListHeader>{t('effects.equalizer')}</ListHeader>
      <Card>
        <div style={{ padding: `12px ${SPACE.s4}px`, borderBottom: `0.5px solid ${C.line}` }}>
          <span style={{ fontSize: 13, color: C.muted }}>{t('effects.preset')}</span>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, paddingTop: 8 }}>
            {PRESETS.concat(preset === 'custom' ? ['custom'] : []).map((name) => {
              const active = preset === name
              return (
                <button
                  key={name}
                  type="button"
                  className="mu-btn mu-press"
                  onClick={() => { if (name !== 'custom') music.updateEffects('preset', { preset: name }) }}
                  style={{
                    padding: '6px 12px', borderRadius: 999, fontSize: 13,
                    background: active
                      ? `color-mix(in srgb, ${C.accent} 18%, transparent)`
                      : `color-mix(in srgb, ${C.muted} 12%, transparent)`,
                    color: active ? C.accent : C.ink,
                  }}
                >
                  {name === 'custom' ? t('effects.custom') : name.charAt(0).toUpperCase() + name.slice(1)}
                </button>
              )
            })}
          </div>
        </div>

        {bands.map((band) => (
          <div
            key={band.index}
            style={{ display: 'flex', alignItems: 'center', gap: 10, padding: `6px ${SPACE.s4}px` }}
          >
            <span className="mu-mono" style={{ fontSize: 11, color: C.muted, width: 40 }}>
              {bandLabel(band.frequencyHz)}
            </span>
            <input
              className="mu-slider"
              style={{ flex: '1 1 auto' }}
              type="range"
              min="-12"
              max="12"
              step="1"
              value={Number(band.gainDB) || 0}
              onChange={(event) => music.updateEffects('set_band', {
                bandIndex: band.index, gainDB: Number(event.target.value),
              })}
            />
            <span className="mu-mono" style={{ fontSize: 11, color: C.muted, width: 30, textAlign: 'right' }}>
              {gainLabel(band.gainDB)}
            </span>
          </div>
        ))}

        <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: `10px ${SPACE.s4}px` }}>
          <span style={{ fontSize: 13, color: C.muted, width: 68 }}>{t('effects.preamp')}</span>
          <input
            className="mu-slider"
            style={{ flex: '1 1 auto' }}
            type="range"
            min="-12"
            max="12"
            step="1"
            value={Number(effects.preampDB) || 0}
            onChange={(event) => music.updateEffects('set_preamp', { preampDB: Number(event.target.value) })}
          />
          <span className="mu-mono" style={{ fontSize: 11, color: C.muted, width: 30, textAlign: 'right' }}>
            {gainLabel(effects.preampDB)}
          </span>
        </div>
      </Card>
      <div style={{ height: 24 }} />
    </div>
  )
}

// For You 发现页（§2.5）。三组横向货架，顺序固定：最近播放 → 为你推荐 → 排行榜。
//
// 与原生的一处结构差异：宿主 `music_recommendations` 把**服务端货架拍平成按类型分组**
// （`{kind, albums, playlists, songs, artists, stations}`），货架标题在工具层就丢了。
// 所以这里按「本地固定的三组 × 类型」排版，拿不到服务端货架名。README 有记。
//
// 数据策略照抄原生三级：会话内存 → 落盘快照秒显（断网也能看）→ 后台拉新，
// **只有非空才覆盖**（无订阅/断网返回空时保留已显示内容，不闪成空态）。

import React from 'react'
import { EmptyState, PullToRefresh, SectionHeader, Artwork, Spinner } from './primitives.jsx'
import { C, SPACE } from './theme.js'
import { music as callMusic, storage, classifyMusicError } from '../lib/host.js'

const SNAPSHOT_KEY = 'music.discovery'
const TTL_MS = 7 * 24 * 3600 * 1000
const KINDS = ['albums', 'playlists', 'songs', 'artists', 'stations']

const session = { data: null }

async function loadShelves({ force }) {
  if (!force && session.data) return session.data
  const [forYou, recent, charts] = await Promise.all([
    callMusic('recommendations', { kind: 'for_you' }),
    callMusic('recommendations', { kind: 'recently_played' }),
    callMusic('recommendations', { kind: 'charts' }),
  ])
  const groups = {
    recent: normalize(recent),
    forYou: normalize(forYou),
    charts: normalize(charts),
  }
  const empty = Object.values(groups).every((group) => group.length === 0)
  if (empty) {
    const failure = classifyMusicError(forYou.error || recent.error || charts.error)
    return { groups: null, failure }
  }
  session.data = { groups, failure: null }
  storage.set(SNAPSHOT_KEY, { at: Date.now(), groups })
  return session.data
}

function normalize(result) {
  if (!result.ok || !result.json) return []
  const payload = result.json
  const out = []
  KINDS.forEach((kind) => {
    const rows = Array.isArray(payload[kind]) ? payload[kind] : []
    if (rows.length > 0) out.push({ kind, items: rows })
  })
  return out
}

export default function ForYouPage({ ctx }) {
  const { t, actions, store } = ctx
  const [state, setState] = React.useState({ loading: true, groups: null, failure: null })
  const [refreshing, setRefreshing] = React.useState(false)
  const [expanding, setExpanding] = React.useState(null)

  const run = React.useCallback(async (force) => {
    const snapshot = force ? null : await storage.get(SNAPSHOT_KEY)
    if (snapshot && snapshot.groups && Date.now() - Number(snapshot.at || 0) < TTL_MS) {
      setState({ loading: false, groups: snapshot.groups, failure: null })
    }
    const result = await loadShelves({ force })
    setState((current) => {
      if (!result.groups) {
        return { loading: false, groups: current.groups, failure: result.failure }
      }
      return { loading: false, groups: result.groups, failure: null }
    })
  }, [])

  React.useEffect(() => { run(false) }, [run])

  const onRefresh = async () => {
    setRefreshing(true)
    await run(true)
    setRefreshing(false)
  }

  const openItem = async (item) => {
    if (item.type === 'station') {
      // 电台在宿主侧**没有任何工具投影**，小应用做不了无尽流。如实说明，不假装能播。
      actions.notice(t('forYou.stationUnsupported'))
      return
    }
    setExpanding(item.musicItemId)
    await actions.openCollection(item)
    setExpanding(null)
  }

  const groups = state.groups
  const sections = groups ? [
    { id: 'recent', title: t('forYou.recentlyPlayed'), size: 132, shelves: groups.recent },
    { id: 'forYou', title: t('forYou.forYou'), size: 164, shelves: groups.forYou },
    { id: 'charts', title: t('forYou.charts'), size: 132, shelves: groups.charts },
  ].filter((section) => section.shelves && section.shelves.length > 0) : []

  return (
    <PullToRefresh onRefresh={onRefresh} refreshing={refreshing}>
      {state.loading && !groups ? (
        <div style={{ padding: 60, display: 'flex', justifyContent: 'center' }}><Spinner color={C.muted} /></div>
      ) : null}

      {sections.length === 0 && !state.loading ? (
        <EmptyState
          icon={state.failure === 'denied' ? 'lock' : 'sparkles'}
          title={state.failure === 'denied' ? t('search.notAuthorized') : t('forYou.empty')}
          hint={state.failure === 'denied' ? t('search.notAuthorizedHint') : t('forYou.emptyHint')}
          top={80}
        />
      ) : null}

      {sections.map((section) => (
        <div key={section.id} style={{ paddingBottom: SPACE.s5 }}>
          <SectionHeader>{section.title}</SectionHeader>
          {section.shelves.map((shelf) => (
            <div
              key={`${section.id}-${shelf.kind}`}
              className="mu-hrow"
              style={{ display: 'flex', gap: 12, padding: `0 ${SPACE.s4}px 4px` }}
            >
              {shelf.items.map((item) => (
                <Card
                  key={`${item.musicItemId}-${item.type}`}
                  item={item}
                  size={section.size}
                  busy={expanding === item.musicItemId}
                  onClick={() => { store.rememberArtwork(item); openItem(item) }}
                  onLongPress={() => actions.collectionMenu(item)}
                />
              ))}
            </div>
          ))}
        </div>
      ))}
      <div style={{ height: 24 }} />
    </PullToRefresh>
  )
}

function Card({ item, size, busy, onClick, onLongPress }) {
  const timer = React.useRef(null)
  return (
    <button
      type="button"
      className="mu-btn mu-press"
      onClick={onClick}
      onPointerDown={() => { timer.current = setTimeout(onLongPress, 500) }}
      onPointerUp={() => { if (timer.current) clearTimeout(timer.current) }}
      onPointerCancel={() => { if (timer.current) clearTimeout(timer.current) }}
      style={{ width: size, flex: '0 0 auto', display: 'flex', flexDirection: 'column', gap: 6 }}
    >
      <div style={{ position: 'relative' }}>
        <Artwork
          url={item.artworkUrl}
          size={size}
          radius={12}
          iconSize={28}
          shadow="0 3px 6px rgba(0,0,0,0.18)"
        />
        {busy ? (
          <div style={{
            position: 'absolute', inset: 0, borderRadius: 12, background: 'rgba(0,0,0,0.35)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
          }}
          >
            <Spinner size={22} color="#fff" />
          </div>
        ) : null}
      </div>
      <span className="mu-clamp-1" style={{ fontSize: 13, fontWeight: 500, color: C.ink, width: size, textAlign: 'left' }}>
        {item.title || item.name}
      </span>
      {item.artist ? (
        <span className="mu-clamp-1" style={{ fontSize: 11, color: C.muted, width: size, textAlign: 'left' }}>
          {item.artist}
        </span>
      ) : null}
    </button>
  )
}

// 资料库页（§2.7）。四段：最近添加 / 本设备 / Apple Music 资料库（五态互斥）/ 我的合集。
//
// 五态的判定在原生是「先授权 → 再探订阅 → 再看是否全空」，靠的是 MusicAuthorization 与
// MusicSubscription 两个独立 API。宿主没有 `availability()` 投影（缺口⑨），
// 这里只能从工具失败文案**反推**——文案变了就会退化成「加载失败」，不会误报成「库为空」。

import React from 'react'
import Icon from './Icon.jsx'
import { Artwork, EmptyState, IconTile, ListHeader, Row, Spinner, Chevron } from './primitives.jsx'
import { C, SPACE } from './theme.js'
import { music as callMusic, classifyMusicError, openURL } from '../lib/host.js'

const CATEGORIES = [
  { id: 'playlists', icon: 'music.note.list', key: 'lib.playlists' },
  { id: 'artists', icon: 'music.mic', key: 'lib.artists' },
  { id: 'albums', icon: 'square.stack', key: 'lib.albums' },
  { id: 'songs', icon: 'music.note', key: 'lib.songs' },
]

const cache = { data: null }

export default function LibraryPage({ ctx }) {
  const { t, store, actions } = ctx
  const [state, setState] = React.useState(() => (cache.data
    ? { status: 'loaded', ...cache.data }
    : { status: 'loading', groups: {}, collections: [] }))

  React.useEffect(() => {
    if (cache.data) return undefined
    let cancelled = false
    const load = async () => {
      const [albums, playlists, songs, artists, collections] = await Promise.all([
        callMusic('library', { action: 'albums', limit: 60 }),
        callMusic('library', { action: 'playlists', limit: 60 }),
        callMusic('library', { action: 'songs', limit: 60 }),
        callMusic('library', { action: 'artists', limit: 60 }),
        callMusic('playlist', { action: 'list', source: 'local' }),
      ])
      if (cancelled) return
      const failure = classifyMusicError(albums.error || playlists.error || songs.error || artists.error)
      const groups = {
        albums: pick(albums, 'albums'),
        playlists: pick(playlists, 'playlists'),
        songs: pick(songs, 'songs'),
        artists: pick(artists, 'artists'),
      }
      Object.values(groups).flat().forEach((row) => store.rememberArtwork(row))
      const local = pick(collections, 'playlists')
      const total = Object.values(groups).reduce((sum, rows) => sum + rows.length, 0)
      let status = 'loaded'
      if (total === 0) {
        if (failure === 'denied') status = 'denied'
        else if (failure === 'noSubscription') status = 'noSubscription'
        else status = 'empty'
      }
      cache.data = { groups, collections: local }
      setState({ status, groups, collections: local })
    }
    load()
    return () => { cancelled = true }
  }, [store])

  const { groups, collections } = state
  const favorites = ctx.favorites

  return (
    <div className="mu-scroll">
      {groups.albums && groups.albums.length > 0 ? (
        <>
          <ListHeader>{t('lib.recentlyAdded')}</ListHeader>
          <div className="mu-hrow" style={{ display: 'flex', gap: 12, padding: `0 ${SPACE.s4}px 4px` }}>
            {groups.albums.slice(0, 10).map((album) => (
              <button
                key={album.musicItemId}
                type="button"
                className="mu-btn mu-press"
                onClick={() => actions.openCollection(album)}
                style={{ width: 120, flex: '0 0 auto', display: 'flex', flexDirection: 'column', gap: 6 }}
              >
                <Artwork url={album.artworkUrl} size={120} radius={8} iconSize={26} />
                <span className="mu-clamp-1" style={{ fontSize: 12, fontWeight: 500, width: 120, textAlign: 'left' }}>
                  {album.title}
                </span>
              </button>
            ))}
          </div>
        </>
      ) : null}

      <ListHeader>{t('lib.onThisDevice')}</ListHeader>
      <Row
        leading={<IconTile name="heart.fill" />}
        title={t('lib.favorites')}
        subtitle={favorites.length > 0 ? t('lib.lovedCount', favorites.length) : t('lib.lovedEmpty')}
        accessory={<Chevron />}
        onClick={() => actions.openSheet('favorites')}
      />
      <Row
        leading={<IconTile name="chart.bar.fill" />}
        title={t('lib.playHistory')}
        subtitle={t('lib.playHistoryHint')}
        accessory={<Chevron />}
        onClick={() => actions.openSheet('history')}
      />
      <Row
        leading={<IconTile name="folder.fill" />}
        title={t('lib.localAudio')}
        subtitle={t('lib.localAudioHint')}
        accessory={<Chevron />}
        onClick={() => actions.navigate({ name: 'local' })}
        last
      />

      <ListHeader>{t('lib.appleMusicLibrary')}</ListHeader>
      {state.status === 'loading' ? (
        <div style={{ padding: 24, display: 'flex', justifyContent: 'center' }}><Spinner color={C.muted} /></div>
      ) : null}
      {state.status === 'denied' ? (
        <EmptyState
          icon="lock.fill"
          title={t('lib.accessNeeded')}
          hint={t('lib.accessNeededHint')}
          top={16}
          action={(
            <button
              type="button"
              className="mu-btn mu-press"
              onClick={() => openURL('app-settings:')}
              style={{
                marginTop: 6, padding: '8px 16px', borderRadius: 999, fontSize: 14, fontWeight: 600,
                background: `color-mix(in srgb, ${C.accent} 15%, transparent)`, color: C.accent,
              }}
            >
              {t('lib.openSettings')}
            </button>
          )}
        />
      ) : null}
      {state.status === 'noSubscription' ? (
        <EmptyState icon="music.note" title={t('lib.subRequired')} hint={t('lib.subRequiredHint')} top={16} />
      ) : null}
      {state.status === 'empty' ? (
        <EmptyState icon="music.note.list" title={t('lib.noSaved')} hint={t('lib.noSavedHint')} top={16} />
      ) : null}
      {state.status === 'loaded' ? CATEGORIES.map((category) => {
        const rows = groups[category.id] || []
        if (rows.length === 0) return null
        return (
          <Row
            key={category.id}
            leading={<IconTile name={category.icon} size={36} radius={8} iconSize={15} />}
            title={t(category.key)}
            detail={rows.length}
            accessory={<Chevron />}
            minHeight={48}
            onClick={() => actions.navigate({ name: 'category', id: category.id, title: t(category.key), items: rows })}
          />
        )
      }) : null}

      {collections && collections.length > 0 ? (
        <>
          <ListHeader>{t('lib.collections')}</ListHeader>
          {collections.map((collection) => (
            <Row
              key={collection.musicItemId}
              leading={<IconTile name="music.note.list" size={36} radius={8} iconSize={15} />}
              title={collection.title || collection.name}
              subtitle={collection.artist}
              accessory={<Chevron />}
              minHeight={48}
              onClick={() => actions.openCollection({ ...collection, type: 'playlist', source: 'local' })}
            />
          ))}
        </>
      ) : null}

      <div style={{ height: 24 }} />
    </div>
  )
}

function pick(result, key) {
  if (!result.ok || !result.json) return []
  const rows = result.json[key]
  return Array.isArray(rows) ? rows : []
}

// 本地曲库浏览（§2.8）。四种模式：专辑 / 艺人 / 歌曲 / 流派。
//
// 三处平台差异（README 有记）：
//  · **没有封面** —— `music_local` 的条目不带封面字段，本地封面是沙盒 file://，WebView 读不到 → 一律音符占位；
//  · **不能导入文件夹** —— 容器只有单文件 picker，没有目录选择与安全书签持久化（缺口⑧）；
//  · **一次最多 500 条** —— `music_local` 的 limit 上限就是 500，超大曲库拿不全。
//
// 专辑/艺人/流派三种分组**在本地从歌曲列表派生**：`music_local` 的 albums/artists 动作
// 只回计数、不回曲目，派生一次反而更省桥调用，也顺带把流派补齐（工具没有 genres 动作）。

import React from 'react'
import Icon from './Icon.jsx'
import { EmptyState, Segmented, Spinner, VirtualList } from './primitives.jsx'
import { LocalTrackRow } from './rows.jsx'
import { C, SPACE } from './theme.js'
import { music as callMusic } from '../lib/host.js'

const LIMIT = 500
const ROW_HEIGHT = 60

export default function LocalLibrary({ ctx }) {
  const { t, actions } = ctx
  const [mode, setMode] = React.useState('albums')
  const [state, setState] = React.useState({ loading: true, tracks: [], issues: [], scanning: false })
  const [drill, setDrill] = React.useState(null)

  const load = React.useCallback(async ({ scan } = {}) => {
    setState((current) => ({ ...current, loading: current.tracks.length === 0, scanning: !!scan }))
    const result = await callMusic('local', { action: scan ? 'scan' : 'list', limit: LIMIT })
    const payload = result.json || {}
    setState({
      loading: false,
      scanning: false,
      tracks: Array.isArray(payload.tracks) ? payload.tracks : [],
      issues: Array.isArray(payload.scanIssues) ? payload.scanIssues : [],
    })
  }, [])

  React.useEffect(() => { load() }, [load])

  const tracks = state.tracks
  const groups = React.useMemo(() => derive(tracks), [tracks])

  if (state.loading) {
    return <div style={{ padding: 60, display: 'flex', justifyContent: 'center' }}><Spinner color={C.muted} /></div>
  }

  if (tracks.length === 0) {
    return (
      <div className="mu-scroll">
        <Toolbar t={t} scanning={state.scanning} onRescan={() => load({ scan: true })} />
        {state.scanning
          ? <EmptyState icon="music.note.list" title={t('local.scanning')} />
          : <EmptyState icon="music.note.list" title={t('local.empty')} hint={t('local.emptyHint')} />}
      </div>
    )
  }

  const playFrom = (list, index) => actions.playTrack(list[index], list)

  if (drill) {
    const list = drill.tracks
    return (
      <VirtualList
        items={list.map((track, i) => ({ ...track, key: track.localTrackId || `${i}` }))}
        itemHeight={ROW_HEIGHT}
        header={(
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: `10px ${SPACE.s4}px` }}>
            <button type="button" className="mu-btn mu-press" onClick={() => setDrill(null)} style={{ color: C.accent }}>
              <Icon name="chevron.backward" size={16} color={C.accent} />
            </button>
            <span style={{ fontSize: 17, fontWeight: 600 }}>{drill.title}</span>
          </div>
        )}
        renderItem={(track, index) => (
          <LocalTrackRow
            track={track}
            onClick={() => playFrom(list, index)}
            onLongPress={() => actions.trackMenu(track, { group: list })}
          />
        )}
        footer={<div style={{ height: 24 }} />}
      />
    )
  }

  const rows = mode === 'songs' ? tracks : groups[mode]

  return (
    <VirtualList
      items={mode === 'songs'
        ? tracks.map((track, i) => ({ ...track, key: track.localTrackId || `${i}` }))
        : rows.map((row) => ({ ...row, key: row.title }))}
      itemHeight={mode === 'songs' ? ROW_HEIGHT : (mode === 'albums' ? 68 : 56)}
      header={(
        <>
          <Toolbar t={t} scanning={state.scanning} onRescan={() => load({ scan: true })} />
          {state.issues.length > 0 ? (
            <div style={{
              margin: `0 ${SPACE.s4}px 12px`, padding: 12, borderRadius: 12, display: 'flex', gap: 10,
              background: `color-mix(in srgb, ${C.warning} 10%, transparent)`,
            }}
            >
              <Icon name="externaldrive.badge.exclamationmark" size={18} color={C.warning} />
              <div style={{ display: 'flex', flexDirection: 'column', gap: 2, minWidth: 0 }}>
                <span style={{ fontSize: 13, fontWeight: 500 }}>{t('local.unavailableTitle')}</span>
                <span style={{ fontSize: 12, color: C.muted, lineHeight: 1.4 }}>{t('local.unavailableHint')}</span>
              </div>
            </div>
          ) : null}
          <div style={{ padding: `0 ${SPACE.s4}px ${SPACE.s2}px` }}>
            <Segmented
              items={[
                { id: 'albums', title: t('local.albums') },
                { id: 'artists', title: t('local.artists') },
                { id: 'songs', title: t('local.songs') },
                { id: 'genres', title: t('local.genres') },
              ]}
              value={mode}
              onChange={setMode}
            />
          </div>
        </>
      )}
      renderItem={(row, index) => {
        if (mode === 'songs') {
          return (
            <LocalTrackRow
              track={row}
              onClick={() => playFrom(tracks, index)}
              onLongPress={() => actions.trackMenu(row, { group: tracks })}
            />
          )
        }
        return (
          <GroupRow
            row={row}
            mode={mode}
            t={t}
            onClick={() => setDrill({ title: row.title, tracks: row.tracks })}
          />
        )
      }}
      footer={<div style={{ height: 24 }} />}
    />
  )
}

function Toolbar({ t, scanning, onRescan }) {
  return (
    <div style={{
      display: 'flex', alignItems: 'center', justifyContent: 'space-between',
      padding: `${SPACE.s2}px ${SPACE.s4}px`,
    }}
    >
      <span style={{ fontSize: 13, color: C.muted }}>{scanning ? t('local.scanning') : t('local.noArtwork')}</span>
      <button type="button" className="mu-btn mu-press" onClick={onRescan} disabled={scanning}
        style={{ display: 'flex', alignItems: 'center', gap: 6, color: C.accent, fontSize: 14, opacity: scanning ? 0.4 : 1 }}
      >
        <Icon name="arrow.clockwise" size={15} color={C.accent} />
        {t('local.rescan')}
      </button>
    </div>
  )
}

function GroupRow({ row, mode, t, onClick }) {
  const icon = mode === 'artists' ? 'music.mic' : (mode === 'genres' ? 'guitars' : 'square.stack')
  const subtitle = mode === 'artists'
    ? t('local.artistSubtitle', row.albumCount, row.tracks.length)
    : (mode === 'albums' ? row.subtitle : null)
  return (
    <button
      type="button"
      className="mu-btn mu-press"
      onClick={onClick}
      style={{ display: 'flex', alignItems: 'center', gap: 12, width: '100%', padding: `8px ${SPACE.s4}px`, height: '100%' }}
    >
      <div style={{ width: 36, display: 'flex', justifyContent: 'center' }}>
        <Icon name={icon} size={16} color={C.accent} />
      </div>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 2, minWidth: 0, flex: '1 1 auto' }}>
        <span className="mu-clamp-1" style={{ fontSize: 15, color: C.ink }}>{row.title}</span>
        {subtitle ? <span className="mu-clamp-1" style={{ fontSize: 12, color: C.muted }}>{subtitle}</span> : null}
      </div>
      {mode === 'genres' ? (
        <span className="mu-mono" style={{ fontSize: 13, color: C.muted }}>{row.tracks.length}</span>
      ) : null}
    </button>
  )
}

/** 从歌曲列表派生专辑 / 艺人 / 流派三种分组。展示回退与原生一致。 */
function derive(tracks) {
  const albums = new Map()
  const artists = new Map()
  const genres = new Map()
  tracks.forEach((track) => {
    const albumName = track.album || 'Unknown Album'
    const artistName = track.artist || 'Unknown Artist'
    const genreName = track.genre || null
    if (!albums.has(albumName)) albums.set(albumName, { title: albumName, subtitle: artistName, tracks: [] })
    albums.get(albumName).tracks.push(track)
    if (!artists.has(artistName)) artists.set(artistName, { title: artistName, tracks: [], albumNames: new Set() })
    const artistRow = artists.get(artistName)
    artistRow.tracks.push(track)
    artistRow.albumNames.add(albumName)
    if (genreName) {
      if (!genres.has(genreName)) genres.set(genreName, { title: genreName, tracks: [] })
      genres.get(genreName).tracks.push(track)
    }
  })
  const sortByTitle = (a, b) => String(a.title).localeCompare(String(b.title))
  return {
    albums: [...albums.values()].sort(sortByTitle),
    artists: [...artists.values()]
      .map((row) => ({ ...row, albumCount: row.albumNames.size }))
      .sort(sortByTitle),
    genres: [...genres.values()].sort(sortByTitle),
  }
}

// 歌词区（§4.7 / §4.9）。四态：加载中 / 有歌词 / 无歌词 / 无当前曲。
//
// 逐行同步的代码结构**已经就位**（当前行、扫光、点行跳转、滚到 40% 高度都实现了），
// 只是今天宿主 `music_lyrics` 返回的是剥掉时间轴的纯文本 → `synced === false`：
// 此时统一按「居中、可滚动的整块文本」渲染，不做高亮、不做扫光、不响应点行跳转。
// 宿主补上 `lines:[{time,text}]` 后，`synced` 变 true，同一份代码自动变成逐行同步。

import React from 'react'
import Icon from './Icon.jsx'
import { Spinner } from './primitives.jsx'
import { WHITE } from './theme.js'
import { currentLineIndex, sweepRatio } from '../lib/lyrics.js'

const SCROLL_IDLE_MS = 1800

export default function Lyrics({ payload, displayTime, onSeek, onUserScroll, t }) {
  const ref = React.useRef(null)
  const lineRefs = React.useRef([])
  const idleTimer = React.useRef(null)
  const [scrolling, setScrolling] = React.useState(false)

  const lines = payload.lines || []
  const synced = !!payload.synced
  const index = synced ? currentLineIndex(lines, displayTime) : -1

  // 当前行变化时滚到卡片 40% 高度处（anchor y = 0.4）。用户正在手动滚动时不抢。
  React.useEffect(() => {
    if (!synced || index < 0 || scrolling) return
    const container = ref.current
    const element = lineRefs.current[index]
    if (!container || !element) return
    const target = element.offsetTop - container.clientHeight * 0.4 + element.clientHeight / 2
    container.scrollTo({ top: Math.max(0, target), behavior: 'smooth' })
  }, [index, synced, scrolling])

  const handleScroll = () => {
    if (!scrolling) { setScrolling(true); onUserScroll(true) }
    if (idleTimer.current) clearTimeout(idleTimer.current)
    idleTimer.current = setTimeout(() => {
      setScrolling(false)
      onUserScroll(false)
    }, SCROLL_IDLE_MS)
  }

  React.useEffect(() => () => { if (idleTimer.current) clearTimeout(idleTimer.current) }, [])

  if (payload.state === 'loading') {
    return (
      <div style={{ flex: '1 1 auto', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <Spinner size={26} color={WHITE.primary} />
      </div>
    )
  }

  if (payload.state !== 'ok' || lines.length === 0) {
    return (
      <div style={{
        flex: '1 1 auto', display: 'flex', flexDirection: 'column', alignItems: 'center',
        justifyContent: 'center', gap: 10, padding: 24, textAlign: 'center', color: WHITE.primary,
      }}
      >
        <Icon name="quote.bubble" size={30} color={WHITE.primary} />
        <span style={{ fontSize: 15, fontWeight: 700 }}>{t('np.lyricsUnavailable')}</span>
        <span style={{ fontSize: 12, lineHeight: 1.45, color: 'rgba(255,255,255,0.65)' }}>
          {t('np.lyricsUnavailableHint')}
        </span>
      </div>
    )
  }

  return (
    <div
      ref={ref}
      className="mu-scroll"
      onScroll={handleScroll}
      style={{
        flex: '1 1 auto',
        padding: '40px 24px 280px',
        // 上下边缘淡出遮罩：透明 @0 / 不透明 @12% / 不透明 @84% / 透明 @100%
        WebkitMaskImage: 'linear-gradient(to bottom, transparent 0%, #000 12%, #000 84%, transparent 100%)',
        maskImage: 'linear-gradient(to bottom, transparent 0%, #000 12%, #000 84%, transparent 100%)',
      }}
    >
      {lines.map((line, i) => (
        <LyricLine
          key={`${i}-${line.time === null ? 'p' : line.time}`}
          ref={(node) => { lineRefs.current[i] = node }}
          line={line}
          active={synced && i === index}
          synced={synced}
          sweep={synced && i === index ? sweepRatio(lines, i, displayTime) : 0}
          onClick={synced && line.time !== null ? () => onSeek(line.time) : undefined}
        />
      ))}
    </div>
  )
}

const LyricLine = React.forwardRef(({ line, active, synced, sweep, onClick }, ref) => {
  const text = line.text && line.text.length > 0 ? line.text : ' '
  // 卡拉OK扫光：仅当前行、仅同步歌词。渐变 stops = [白 @0, 白 @sweep, 白45% @sweep+0.03, 白45% @1]
  const sweepStyle = active ? {
    backgroundImage: `linear-gradient(to right, ${WHITE.primary} 0%, ${WHITE.primary} ${sweep * 100}%, rgba(255,255,255,0.45) ${Math.min(1, sweep + 0.03) * 100}%, rgba(255,255,255,0.45) 100%)`,
    WebkitBackgroundClip: 'text',
    backgroundClip: 'text',
    color: 'transparent',
  } : {}

  return (
    <div
      ref={ref}
      onClick={onClick}
      role={onClick ? 'button' : undefined}
      style={{
        padding: '8px 0',
        marginBottom: 6,
        cursor: onClick ? 'pointer' : 'default',
        transformOrigin: 'left center',
        transform: synced ? `scale(${active ? 1 : 0.94})` : 'none',
        opacity: synced ? (active ? 1 : 0.4) : 0.92,
        transition: 'opacity 0.28s ease-out, transform 0.28s cubic-bezier(0.2,0.8,0.3,1)',
      }}
    >
      <div style={{
        fontSize: 24,
        fontWeight: 700,
        lineHeight: 1.28,
        color: WHITE.primary,
        textAlign: synced ? 'left' : 'center',
        ...sweepStyle,
      }}
      >
        {text}
      </div>
      {line.translation ? (
        <div style={{
          fontSize: 17, fontWeight: 500, marginTop: 4,
          color: active ? 'rgba(255,255,255,0.88)' : 'rgba(255,255,255,0.45)',
          textAlign: synced ? 'left' : 'center',
        }}
        >
          {line.translation}
        </div>
      ) : null}
    </div>
  )
})
LyricLine.displayName = 'LyricLine'

// mini 播放条（§3.3）。**只在非 Now Playing tab 出现**，且必须有当前曲目。
// 手势：整条支持**上滑展开** —— 拖拽超过 25px 即切到 Now Playing（不只是点击）。

import React from 'react'
import Icon from './Icon.jsx'
import { Artwork, Spinner } from './primitives.jsx'
import { C } from './theme.js'

export default function MiniBar({ track, isPlaying, busy, progress, onOpen, onToggle, onNext, t }) {
  const start = React.useRef(null)
  const [lift, setLift] = React.useState(0)
  if (!track) return null

  return (
    <div
      aria-label="audioMiniBar"
      style={{
        flex: '0 0 auto', padding: '0 12px 4px',
        transform: `translateY(${-lift}px)`,
        transition: start.current ? 'none' : 'transform 0.18s ease-out',
      }}
      onPointerDown={(event) => { start.current = { y: event.clientY, moved: false } }}
      onPointerMove={(event) => {
        if (!start.current) return
        const delta = event.clientY - start.current.y
        if (delta < -3) start.current.moved = true
        setLift(Math.max(0, Math.min(40, -delta)))
      }}
      onPointerUp={(event) => {
        const info = start.current
        start.current = null
        setLift(0)
        if (!info) return
        // translation.height < -25 即展开（与原生同阈值）
        if (event.clientY - info.y < -25) onOpen()
      }}
      onPointerCancel={() => { start.current = null; setLift(0) }}
    >
      <div style={{
        display: 'flex', alignItems: 'center', gap: 12, padding: '8px 16px',
        borderRadius: 16, background: C.glass,
        backdropFilter: 'blur(24px)', WebkitBackdropFilter: 'blur(24px)',
        boxShadow: '0 4px 10px rgba(0,0,0,0.12)', position: 'relative', overflow: 'hidden',
      }}
      >
        <button
          type="button"
          className="mu-btn mu-press"
          onClick={onOpen}
          style={{ display: 'flex', alignItems: 'center', gap: 12, flex: '1 1 auto', minWidth: 0 }}
        >
          <Artwork url={track.artworkUrl} size={40} radius={7} iconSize={16} />
          <div style={{ display: 'flex', flexDirection: 'column', gap: 1, minWidth: 0, flex: '1 1 auto' }}>
            <span className="mu-clamp-1" style={{ fontSize: 14, fontWeight: 600, color: C.ink }}>
              {track.title || t('np.notPlaying')}
            </span>
            {track.artist ? (
              <span className="mu-clamp-1" style={{ fontSize: 12, color: C.muted }}>{track.artist}</span>
            ) : null}
          </div>
        </button>

        <button
          type="button"
          className="mu-btn mu-press"
          onClick={onToggle}
          style={{ width: 36, height: 36, display: 'flex', alignItems: 'center', justifyContent: 'center', color: C.ink }}
        >
          {busy ? <Spinner size={18} color={C.ink} /> : <Icon name={isPlaying ? 'pause.fill' : 'play.fill'} size={22} />}
        </button>
        <button
          type="button"
          className="mu-btn mu-press"
          onClick={onNext}
          style={{ width: 32, height: 36, display: 'flex', alignItems: 'center', justifyContent: 'center', color: C.ink }}
        >
          <Icon name="forward.fill" size={18} />
        </button>

        {/* 底部 2pt 进度线 */}
        <div style={{ position: 'absolute', left: 0, right: 0, bottom: 0, height: 2, background: `color-mix(in srgb, ${C.muted} 18%, transparent)` }}>
          <div style={{ width: `${Math.max(0, Math.min(1, progress)) * 100}%`, height: '100%', background: C.accent }} />
        </div>
      </div>
    </div>
  )
}

// Now Playing（§2.1）。**普通独立页**，不是下拉抽屉、不是沉浸 overlay，本页自身没有任何拖拽手势。
// 两个就地切换的形态（专辑 / 歌词）**共享底部控件组**。

import React from 'react'
import Icon from './Icon.jsx'
import { Artwork, ToastCapsule } from './primitives.jsx'
import { Scrubber, TransportBar } from './PlayerControls.jsx'
import Lyrics from './Lyrics.jsx'
import { WHITE } from './theme.js'
import { rgba, sizedArtworkURL, artworkDataURL } from '../lib/artwork.js'

const MAX_COVER = 340

export default function NowPlaying({
  track, status, busy, progress, position, duration, artworkURL, color,
  lyrics, mode, onSetMode, isFavorite, onToggleFavorite, onOpenTrackMenu,
  scrub, onPrevious, onNext, onTogglePlay, onSeekSeconds, onRetry, t,
}) {
  const [controlsHidden, setControlsHidden] = React.useState(false)
  const [toast, setToast] = React.useState(null)
  const toastTimer = React.useRef(null)

  const showToast = (message) => {
    setToast(message)
    if (toastTimer.current) clearTimeout(toastTimer.current)
    toastTimer.current = setTimeout(() => setToast(null), 2000)
  }
  React.useEffect(() => () => { if (toastTimer.current) clearTimeout(toastTimer.current) }, [])

  const toggleMode = () => {
    if (!track) { showToast(t('np.lyricsUnavailable')); return }
    onSetMode(mode === 'lyrics' ? 'album' : 'lyrics')
    if (mode === 'lyrics') setControlsHidden(false)
  }

  const failed = status.playbackState === 'failed'

  return (
    <div style={{ position: 'relative', flex: '1 1 auto', minHeight: 0, display: 'flex', flexDirection: 'column' }}>
      <Ambient url={artworkURL} color={color} dim={mode === 'lyrics'} />

      <div style={{
        position: 'relative', zIndex: 1, flex: '1 1 auto', minHeight: 0,
        display: 'flex', flexDirection: 'column',
        padding: '12px 20px 20px', color: WHITE.primary,
      }}
      >
        {mode === 'lyrics' ? (
          <>
            <LyricsHeader
              track={track}
              artworkURL={artworkURL}
              isFavorite={isFavorite}
              onToggleFavorite={onToggleFavorite}
              onOpenTrackMenu={onOpenTrackMenu}
              onBack={() => { onSetMode('album'); setControlsHidden(false) }}
              t={t}
            />
            <Lyrics
              payload={lyrics}
              displayTime={position}
              onSeek={onSeekSeconds}
              onUserScroll={setControlsHidden}
              t={t}
            />
          </>
        ) : (
          <>
            <div style={{ flex: '0 1 16px', minHeight: 16 }} />
            <CoverArea
              url={artworkURL}
              playing={status.isPlaying}
              onTap={toggleMode}
              onLyrics={toggleMode}
            />
            <div style={{ height: 24, flex: '0 0 auto' }} />
            <TitleRow
              track={track}
              isFavorite={isFavorite}
              onToggleFavorite={onToggleFavorite}
              onOpenTrackMenu={onOpenTrackMenu}
              t={t}
            />
            <div style={{ flex: '1 1 20px', minHeight: 20 }} />
          </>
        )}

        <div style={{
          display: 'flex', flexDirection: 'column', gap: 20, flex: '0 0 auto',
          maxHeight: controlsHidden ? 0 : 200,
          opacity: controlsHidden ? 0 : 1,
          overflow: 'hidden',
          transform: controlsHidden ? 'translateY(24px)' : 'none',
          transition: 'opacity 0.28s ease-in-out, transform 0.28s ease-in-out, max-height 0.28s ease-in-out',
        }}
        >
          <Scrubber
            progress={progress}
            position={position}
            duration={duration}
            onBegin={scrub.begin}
            onChange={scrub.update}
            onEnd={scrub.end}
          />
          <TransportBar
            isPlaying={status.isPlaying}
            busy={busy}
            disabled={!track}
            onPrevious={onPrevious}
            onToggle={onTogglePlay}
            onNext={onNext}
          />
        </div>
      </div>

      {failed ? <FailureCard status={status} onRetry={onRetry} t={t} /> : null}
      <ToastCapsule message={toast} />
    </div>
  )
}

/** 氛围背景：自下而上 5 层，铺满全屏（含安全区）。 */
function Ambient({ url, color, dim }) {
  const [dataURL, setDataURL] = React.useState(null)
  const target = url ? sizedArtworkURL(url, 200) : null
  React.useEffect(() => {
    let cancelled = false
    setDataURL(null)
    if (!target) return undefined
    artworkDataURL(target).then((value) => { if (!cancelled) setDataURL(value) })
    return () => { cancelled = true }
  }, [target])

  const base = color ? rgba(color, 0.55) : 'rgba(255,107,107,0.55)'
  const mid = color ? rgba(color, 0.16) : 'rgba(255,107,107,0.16)'
  return (
    <div className="mu-ambient">
      {/* ① 纯黑打底：保证任意专辑色下白控件都可读 */}
      <div style={{ background: '#000' }} />
      {/* ② 模糊封面（被有具体尺寸的容器裁住，绝不撑开父级） */}
      {dataURL ? <img className="mu-ambient-blur" src={dataURL} alt="" /> : null}
      {/* ③ 专辑取色线性渐变 top→bottom */}
      <div style={{
        background: `linear-gradient(to bottom, ${base} 0%, ${mid} 55%, rgba(0,0,0,0.35) 100%)`,
        transition: 'background 0.4s ease-in-out',
      }}
      />
      {/* ④ 底部加深（下半屏是控件密集区） */}
      <div style={{ background: 'linear-gradient(to bottom, transparent 50%, rgba(0,0,0,0.5) 100%)' }} />
      {/* ⑤ 歌词态再整体压一层 */}
      <div style={{
        background: 'rgba(0,0,0,0.28)',
        opacity: dim ? 1 : 0,
        transition: 'opacity 0.35s ease-in-out',
      }}
      />
    </div>
  )
}

