/**
 * 封面。
 * **布局红线**：`.fill` 的图必须被有具体尺寸的容器裁住（`overflow:hidden` + 明确宽高 +
 * `object-fit:cover`），绝不能让图撑开父级——原生历史 bug「Now Playing 控件不显示」的真根因
 * 就是封面溢出把两侧控件挤出屏幕。
 *
 * 取图路径：远程 URL → `aibox.net.fetch(base64)` → data URL（secure 模式 CSP 拦掉远程 <img>）。
 */
export function Artwork({
  url, size, radius = 8, iconSize, tint = C.accent, background, className, shadow, style,
}) {
  const [dataURL, setDataURL] = React.useState(null)
  // size 允许传 '100%'（大封面按容器铺满）；此时取图尺寸用固定 600，占位图标必须显式给 iconSize。
  const numeric = typeof size === 'number' ? size : null
  const target = url
    ? sizedArtworkURL(url, numeric ? Math.min(600, Math.max(120, Math.round(numeric * 2))) : 600)
    : null
  React.useEffect(() => {
    let cancelled = false
    setDataURL(null)
    if (!target) return undefined
    artworkDataURL(target).then((value) => { if (!cancelled) setDataURL(value) })
    return () => { cancelled = true }
  }, [target])

  const glyph = iconSize || (numeric ? Math.max(12, Math.round(numeric * 0.32)) : 40)
  return (
    <div
      className={className}
      style={{
        position: 'relative',
        width: size,
        height: size,
        minWidth: numeric || 0,
        borderRadius: radius,
        overflow: 'hidden',
        flex: '0 0 auto',
        background: background || `color-mix(in srgb, ${tint} 12%, transparent)`,
        boxShadow: shadow,
        ...style,
      }}
    >
      <div style={{
        position: 'absolute', inset: 0, display: 'flex',
        alignItems: 'center', justifyContent: 'center',
      }}
      >
        <Icon name="music.note" size={glyph} color={`color-mix(in srgb, ${tint} 50%, transparent)`} />
      </div>
      {dataURL ? (
        <img
          src={dataURL}
          alt=""
          style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover' }}
        />
      ) : null}
    </div>
  )
}

/**
 * 虚拟列表。
 * 本应用**不能** `import { VirtualList } from 'aibox/ui'` —— 市场校验的离线裸模块白名单里没有它
 * （只有 react / react-dom / antd-mobile / chart.js），引用会在提交前被 validate.mjs 拒掉，
 * 运行时也会白屏。所以这里写一个**同接口**的等价实现；宿主哪天把 `aibox/ui` 放进白名单，
 * 只要接口一致就能整体替换。
 *
 * 接口：`<VirtualList items itemHeight renderItem overscan header footer />`
 */
export function VirtualList({
  items, itemHeight, renderItem, overscan = 6, header, footer, className = 'mu-scroll', style, onScroll,
}) {
  const ref = React.useRef(null)
  const [scrollTop, setScrollTop] = React.useState(0)
  const [viewport, setViewport] = React.useState(600)

  React.useEffect(() => {
    const element = ref.current
    if (!element) return undefined
    const measure = () => setViewport(element.clientHeight || 600)
    measure()
    if (typeof ResizeObserver === 'undefined') return undefined
    const observer = new ResizeObserver(measure)
    observer.observe(element)
    return () => observer.disconnect()
  }, [])

  const total = items.length
  const first = Math.max(0, Math.floor(scrollTop / itemHeight) - overscan)
  const visible = Math.min(total - first, Math.ceil(viewport / itemHeight) + overscan * 2)
  const slice = items.slice(first, first + Math.max(0, visible))

  return (
    <div
      ref={ref}
      className={className}
      style={style}
      onScroll={(event) => {
        setScrollTop(event.currentTarget.scrollTop)
        if (onScroll) onScroll(event)
      }}
    >
      {header}
      <div style={{ height: total * itemHeight, position: 'relative' }}>
        <div style={{ position: 'absolute', top: first * itemHeight, left: 0, right: 0 }}>
          {slice.map((item, offset) => (
            <div key={item.key || item.id || (first + offset)} style={{ height: itemHeight }}>
              {renderItem(item, first + offset)}
            </div>
          ))}
        </div>
      </div>
      {footer}
    </div>
  )
}

