/** 长按（500ms）不触发 click；移动超过 10px 视为滚动，取消长按。 */
export function useLongPress(onLongPress, { delay = 500 } = {}) {
  const timer = React.useRef(null)
  const origin = React.useRef(null)
  const fired = React.useRef(false)

  const clear = () => {
    if (timer.current) { clearTimeout(timer.current); timer.current = null }
  }
  // 返回 { bind, consumed } 而不是把 consumedClick 混在事件处理器里——
  // 后者会被 `{...press}` 原样铺到 DOM 节点上，React 会告警「无法识别的属性」。
  return {
    bind: {
      onPointerDown: (event) => {
        fired.current = false
        origin.current = { x: event.clientX, y: event.clientY }
        clear()
        timer.current = setTimeout(() => {
          fired.current = true
          onLongPress()
        }, delay)
      },
      onPointerMove: (event) => {
        if (!origin.current) return
        const dx = Math.abs(event.clientX - origin.current.x)
        const dy = Math.abs(event.clientY - origin.current.y)
        if (dx > 10 || dy > 10) clear()
      },
      onPointerUp: clear,
      onPointerCancel: clear,
      onPointerLeave: clear,
    },
    consumed: () => fired.current,
  }
}

/** 左滑露出一个操作（删除 / 移除）。手势本身即明确意图，不再二次确认。 */
export function SwipeRow({ children, actionLabel, onAction, danger = true }) {
  const [offset, setOffset] = React.useState(0)
  const start = React.useRef(null)
  const width = 84
  return (
    <div style={{ position: 'relative', overflow: 'hidden' }}>
      <button
        type="button"
        className="mu-btn mu-press"
        onClick={() => { setOffset(0); onAction() }}
        style={{
          position: 'absolute', top: 0, bottom: 0, right: 0, width,
          background: danger ? C.danger : C.muted, color: '#fff', fontSize: 14,
          display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}
      >
        {actionLabel}
      </button>
      <div
        onPointerDown={(event) => { start.current = { x: event.clientX, base: offset } }}
        onPointerMove={(event) => {
          if (!start.current) return
          const delta = event.clientX - start.current.x
          const next = Math.max(-width, Math.min(0, start.current.base + delta))
          setOffset(next)
        }}
        onPointerUp={() => {
          if (!start.current) return
          setOffset(offset < -width / 2 ? -width : 0)
          start.current = null
        }}
        onPointerCancel={() => { start.current = null; setOffset(0) }}
        style={{
          transform: `translateX(${offset}px)`,
          transition: start.current ? 'none' : 'transform 0.18s ease-out',
          background: C.bg,
          position: 'relative',
        }}
      >
        {children}
      </div>
    </div>
  )
}

