export function FavoritesSheet({ open, onClose, ctx }) {
  const { t, actions, favorites, favoritesLoading } = ctx
  return (
    <Sheet
      open={open}
      onClose={onClose}
      title={t('fav.title')}
      trailing={(
        <button type="button" className="mu-btn mu-press" onClick={onClose} style={{ color: C.accent, fontSize: 16 }}>
