// 语言：跟随宿主有效 UI 语言（documentStart 就写好的 window.__aiboxEnvironment），
// 并监听 `environment.localeChanged` 重渲染（不重载 WebView）。

import { STRINGS } from './strings.js'

/** 宿主 locale → 本包支持的语言键（zh-Hans 与 en 两档，其余回落 en）。 */
export function normalizeLocale(locale) {
  const raw = String(locale || 'en').toLowerCase()
  if (raw.startsWith('zh')) return 'zh-Hans'
  return 'en'
}

export function currentLocale() {
  const env = typeof window !== 'undefined' ? window.__aiboxEnvironment : null
  return normalizeLocale(env && (env.locale || env.language))
}

/** 订阅宿主语言变化；返回退订函数。 */
export function onLocaleChanged(handler) {
  const bus = typeof window !== 'undefined' && window.aibox && window.aibox.events
  if (!bus || typeof bus.on !== 'function') return () => {}
  return bus.on('environment.localeChanged', (payload) => {
    handler(normalizeLocale(payload && (payload.locale || payload.language)))
  })
}

/** 缺键时回落 en，再回落键名本身（便于发现漏键，不会渲染成空白）。 */
export function translate(locale, key) {
  const table = STRINGS[locale] || STRINGS.en
  if (table[key] !== undefined) return table[key]
  if (STRINGS.en[key] !== undefined) return STRINGS.en[key]
  return key
}

export function fmt(template, ...args) {
  return String(template).replace(/\{(\d+)\}/g, (whole, index) => {
    const value = args[Number(index)]
    return value === undefined || value === null ? whole : String(value)
  })
}

export function makeT(locale) {
  return (key, ...args) => {
    const value = translate(locale, key)
    return args.length > 0 ? fmt(value, ...args) : value
  }
}

export function bcp47(locale) {
  return locale === 'zh-Hans' ? 'zh-CN' : 'en-US'
}

// 对外动作（AI / 自动化 / 快捷指令可调用）。
//
// 刻意**不**重复宿主已有的 19 个 `music_*` 工具——那些是原生 AiBoxMusicKit 提供的，
// 重复声明只会造成重名混淆。这里只声明「宿主工具覆盖不到」的编排型能力：
//  · nowPlayingSummary —— 一次调用拿到 状态 + 队列摘要 + 定时器 + 歌词可用性（省 3 趟工具调用）
//  · playMostPlayed    —— 按**本应用自己的播放历史**排名起播（没有任何宿主工具能读播放历史）
//  · resumeLast        —— 回到本应用记的上次播放位置（没有任何宿主工具能读它）
//
// 硬要求：全部 **headless 可跑** —— 只依赖 `aibox.music.*` 与 `aibox.storage`，
// 不读任何 React state；「歌词当前行」这类依赖页面内存的，直接如实回 null 并说明原因。

import { music as callMusic, storage } from './host.js'
import { readLyricsPayload, currentLineIndex } from './lyrics.js'
import { playArgs } from './format.js'

async function readStatus() {
  const result = await callMusic('status', {})
  return (result.ok && result.json) ? result.json : null
}

/** 当前播放摘要。read / idempotent / headless。 */
export async function nowPlayingSummary() {
  const [statusResult, queueResult, timerResult] = await Promise.all([
    callMusic('status', {}),
    callMusic('queue', { action: 'list' }),
    callMusic('sleepTimer', { action: 'status' }),
  ])
  const status = (statusResult.ok && statusResult.json) ? statusResult.json : null
  if (!status) {
    return { ok: false, message: statusResult.error || 'Music engine unavailable.' }
  }
  const rows = Array.isArray(queueResult.json) ? queueResult.json : []
  const index = Number(status.currentIndex)
  const upNext = rows
    .filter((row) => Number(row.index) > index)
    .slice(0, 5)
    .map((row) => ({ title: row.title, artist: row.artist || null, index: row.index }))

  let lyrics = { available: false, synced: false, currentLine: null, note: null }
  if (status.currentTrack) {
    const payload = readLyricsPayload(await callMusic('lyrics', {}))
    const line = payload.synced
      ? currentLineIndex(payload.lines, Number(status.currentTime) || 0)
      : -1
    lyrics = {
      available: payload.state === 'ok',
      synced: payload.synced,
      currentLine: line >= 0 ? payload.lines[line].text : null,
      // 如实说明：宿主 `music_lyrics` 返回的是剥掉时间轴的纯文本，所以当前行通常拿不到。
      note: payload.synced ? null : 'The host returns lyrics without a timeline, so the current line is unknown.',
    }
  }

  return {
    ok: true,
    isPlaying: !!status.isPlaying,
    playbackState: status.playbackState || 'idle',
    track: status.currentTrack || null,
    positionSeconds: Math.max(0, Math.floor(Number(status.currentTime) || 0)),
    durationSeconds: Math.max(0, Math.floor(Number(status.duration) || 0)),
    queueCount: Number(status.queueCount) || 0,
    currentIndex: Number.isFinite(index) ? index : -1,
    upNext,
    repeatMode: status.repeatMode || 'off',
    isShuffled: !!status.isShuffled,
    volume: Number(status.volume),
    sleepTimer: timerResult.ok ? String(timerResult.text || '').trim() : null,
    lyrics,
  }
}

/** 按本应用的播放历史排名起播。write / mediaPlayback / headless。 */
export async function playMostPlayed(input) {
  const limit = Math.max(1, Math.min(50, Number(input && input.limit) || 20))
  const history = await storage.get('music.playHistory')
  const rows = Array.isArray(history) ? history.filter((row) => row && row.track) : []
  if (rows.length === 0) {
    return { ok: false, queued: 0, startedWith: null, message: 'No play history yet — play something first.' }
  }
  const ranked = rows
    .slice()
    .sort((a, b) => (b.count - a.count) || (b.lastPlayed - a.lastPlayed))
    .slice(0, limit)
    .map((row) => playArgs(row.track))
  const first = ranked[0]
  const result = await callMusic('play', { ...first, queue: ranked })
  return {
    ok: result.ok,
    queued: result.ok ? ranked.length : 0,
    startedWith: result.ok ? (first.title || null) : null,
    message: result.ok ? `Playing ${ranked.length} most-played tracks.` : String(result.error || 'Playback failed.'),
  }
}

/** 接着上次继续听。write / mediaPlayback / headless。 */
export async function resumeLast() {
  const ui = await storage.get('music.uiState')
  const track = ui && ui.lastTrack
  if (!track || !track.title) {
    return { ok: false, track: null, positionSeconds: 0, message: 'No previous track recorded.' }
  }
  const position = Math.max(0, Math.floor(Number(ui.lastPosition) || 0))

  // 已经在放同一首就只补 seek，不重新起播（重新起播会打断，且会重置队列）。
  const status = await readStatus()
  const same = status && status.currentTrack
    && (String(status.currentTrack.musicItemId || status.currentTrack.url || '')
      === String(track.musicItemId || track.url || ''))
  if (same) {
    if (position > 1) await callMusic('seek', { seconds: position })
    if (!status.isPlaying) await callMusic('transport', { action: 'resume' })
    return { ok: true, track, positionSeconds: position, message: 'Resumed the current track.' }
  }

  const result = await callMusic('play', playArgs(track))
  if (!result.ok) {
    return { ok: false, track, positionSeconds: position, message: String(result.error || 'Playback failed.') }
  }
  if (position > 1) await callMusic('seek', { seconds: position })
  return { ok: true, track, positionSeconds: position, message: `Resumed “${track.title}” at ${position}s.` }
}

/** manifest.actions 里声明的 name → 处理器。app.jsx 启动时逐个 register。 */
export const ACTION_HANDLERS = {
  nowPlayingSummary,
  playMostPlayed,
  resumeLast,
}

// 封面与专辑主色。
//
// 两个绕不开的平台事实：
//  1. secure 模式 CSP 是 `img-src applet: data: blob:` —— **远程 URL 的 <img> 会被整条拦掉**。
//     所以封面统一走 `aibox.net.fetch(responseType:'base64')` → `data:` URL。
//     附带好处：data URL 是同源的，canvas `getImageData` 不会被跨域污染，取色才可能。
//  2. `music_status.currentTrack` 用的是 `AudioTrack.toolJSON`，**不含 artworkUrl**；
//     `music_local` 的条目也没有封面字段。所以封面要靠「搜索/推荐/资料库结果里见过就记下来」
//     这条旁路补齐（见 store.rememberArtwork），本地曲目则永远是音符占位。

import { fetchImageDataURL } from './host.js'
import { stableKey } from './format.js'

const dataURLCache = new Map()
const inflight = new Map()
const colorCache = new Map()
const MAX_CACHE = 60

/** 取封面的 data URL（内存缓存 + 同 URL 请求去重）。失败回 null，调用方显示占位。 */
export async function artworkDataURL(url) {
  const key = String(url || '')
  if (!key) return null
  if (dataURLCache.has(key)) return dataURLCache.get(key)
  if (inflight.has(key)) return inflight.get(key)
  const task = fetchImageDataURL(key).then((value) => {
    inflight.delete(key)
    if (dataURLCache.size >= MAX_CACHE) dataURLCache.delete(dataURLCache.keys().next().value)
    dataURLCache.set(key, value)
    return value
  }).catch(() => {
    inflight.delete(key)
    return null
  })
  inflight.set(key, task)
  return task
}

/** Apple Music 的封面 URL 常带 `{w}x{h}bb.jpg` 尺寸段，按需换成目标边长省流量。 */
export function sizedArtworkURL(url, size) {
  const value = String(url || '')
  if (!value) return value
  return value.replace(/\/(\d+)x(\d+)([a-z-]*\.(?:jpg|jpeg|png|webp))/i, `/${size}x${size}$3`)
}

/**
 * 专辑主色（氛围渐变底用）。
 * 原生取的是 Apple Music 服务端给的官方 `Artwork.backgroundColor`；容器没有透出（缺口 #4），
 * 这里退而求其次：把封面画进 8×8 的 canvas，取加权平均后再拉高饱和度。是**近似**，不是同一个值。
 */
export async function dominantColor(dataURL) {
  const key = String(dataURL || '').slice(0, 128)
  if (!key) return null
  if (colorCache.has(key)) return colorCache.get(key)
  try {
    const color = await new Promise((resolve) => {
      const image = new Image()
      image.onload = () => {
        try {
          const canvas = document.createElement('canvas')
          canvas.width = 8
          canvas.height = 8
          const context = canvas.getContext('2d', { willReadFrequently: true })
          if (!context) { resolve(null); return }
          context.drawImage(image, 0, 0, 8, 8)
          resolve(averageColor(context.getImageData(0, 0, 8, 8).data))
        } catch (error) {
          // 跨域污染或 canvas 不可用：如实回 null，调用方用 accent 兜底。
          resolve(null)
        }
      }
      image.onerror = () => resolve(null)
      image.src = dataURL
    })
    if (colorCache.size >= MAX_CACHE) colorCache.delete(colorCache.keys().next().value)
    colorCache.set(key, color)
    return color
  } catch (error) {
    return null
  }
}

/** 取「够鲜艳且够暗」的平均色：跳过接近纯白/纯黑的像素，再把饱和度拉到可用区间。 */
function averageColor(pixels) {
  let r = 0
  let g = 0
  let b = 0
  let count = 0
  for (let i = 0; i < pixels.length; i += 4) {
    const alpha = pixels[i + 3]
    if (alpha < 24) continue
    const pr = pixels[i]
    const pg = pixels[i + 1]
    const pb = pixels[i + 2]
    const max = Math.max(pr, pg, pb)
    const min = Math.min(pr, pg, pb)
    if (max < 24 || min > 236) continue
    r += pr
    g += pg
    b += pb
    count += 1
  }
  if (count === 0) return null
  return boost({ r: Math.round(r / count), g: Math.round(g / count), b: Math.round(b / count) })
}

function boost(color) {
  const max = Math.max(color.r, color.g, color.b)
  const min = Math.min(color.r, color.g, color.b)
  const saturation = max === 0 ? 0 : (max - min) / max
  // 太灰的封面（黑白照）直接原样返回，硬拉饱和度只会出脏色。
  if (saturation < 0.08 || max === 0) return color
  const target = Math.min(190, Math.max(96, max))
  const scale = target / max
  return {
    r: Math.min(255, Math.round(color.r * scale)),
    g: Math.min(255, Math.round(color.g * scale)),
    b: Math.min(255, Math.round(color.b * scale)),
  }
}

export function rgba(color, alpha) {
  if (!color) return `rgba(255,107,107,${alpha})`
  return `rgba(${color.r},${color.g},${color.b},${alpha})`
}

/**
 * 补齐当前曲的封面 URL：`music_status` 不给，只能反查一次目录搜索并记进映射表。
 * 只对 Apple Music 曲目做（本地曲目服务端没有对应条目），且每个 key 只查一次。
 */
const backfilled = new Set()

export async function backfillArtworkURL(track, { store, music }) {
  if (!track || !track.musicItemId) return null
  const key = stableKey(track)
  if (!key || backfilled.has(key)) return store.artworkURL(track)
  backfilled.add(key)
  const query = [track.title, track.artist].filter(Boolean).join(' ')
  if (!query) return null
  const result = await music('search', { query, types: ['song'], limit: 5 })
  const songs = (result.json && Array.isArray(result.json.songs)) ? result.json.songs : []
  const hit = songs.find((row) => String(row.musicItemId) === String(track.musicItemId))
    || songs.find((row) => String(row.title || '').toLowerCase() === String(track.title || '').toLowerCase())
  if (hit && (hit.artworkUrl || hit.url)) {
    // 顺带把 Apple Music 页面链接记下来——`music_status` 也不给 externalURL，分享要用。
    store.rememberArtwork({ ...track, artworkUrl: hit.artworkUrl, url: hit.url })
    return hit.artworkUrl || null
  }
  return null
}

// 平滑播放时钟（规格 §4.7 的移植版）。
//
// 为什么必须有它：容器只给 `music_status` 轮询，且 `currentTime` 是**取整到秒的整数**
// （framework-capabilities.md §3.6.1 缺口 #1）。直接把整数秒喂给进度条 / 歌词，
// 视觉上就是每秒跳一格。这里用「轮询锚点 + 单调时钟插值」把它铺平。
//
// 三条与原生一致的纪律：
//  1. **不用墙钟**（Date.now 会被系统时间校正跳变），用 performance.now 的单调运行时间；
//  2. 暂停 / 忙（loading、buffering）时**有效速率为 0**，歌词与进度冻结，不空转；
//  3. 切歌 / seek / stop 递增时间线版本号 → 强制重新锚定。
//
// 相对原生的额外一招：整数秒的**进位沿**是免费的高精度信息。
// 轮询到 `reported` 比上一次大 1 时，说明「这一秒刚刚跨过去」，误差不超过一个轮询周期，
// 于是把锚点钉在那一刻；同一秒内的重复观测只用来兜底纠偏，不重新锚定。

const DEFAULT_NOW = () => (typeof performance !== 'undefined' && performance.now
  ? performance.now()
  : Date.now())

export class SmoothClock {
  constructor({ now = DEFAULT_NOW } = {}) {
    this.now = now
    this.reset()
  }

  reset() {
    this.anchorMedia = 0
    this.anchorUptime = this.now()
    this.rate = 0
    this.duration = 0
    this.lastReported = null
    this.timeline = 0
    this.anchoredOnEdge = false
  }

  /** 有效速率：暂停 / 忙 → 0；本地音效路径 → 实际倍速；Apple Music 与普通本地 → 1。 */
  static effectiveRate({ playbackState, isPlaying, effectsRate = 1, appliesEffects = false }) {
    if (playbackState === 'loading' || playbackState === 'buffering') return 0
    if (playbackState === 'failed' || playbackState === 'idle') return 0
    if (!isPlaying && playbackState !== 'playing') return 0
    return appliesEffects ? Math.max(0.25, Math.min(4, Number(effectsRate) || 1)) : 1
  }

  /** 强制重新锚定（切歌 / seek / stop 后调用）。 */
  reanchor(seconds, { duration, rate, timeline } = {}) {
    this.anchorMedia = clamp(Number(seconds) || 0, 0, duration === undefined ? Infinity : duration)
    this.anchorUptime = this.now()
    if (duration !== undefined) this.duration = Math.max(0, Number(duration) || 0)
    if (rate !== undefined) this.rate = Math.max(0, Number(rate) || 0)
    if (timeline !== undefined) this.timeline = timeline
    this.lastReported = Math.floor(this.anchorMedia)
    this.anchoredOnEdge = true
  }

  /**
   * 吃一次轮询快照。`reported` 是整数秒。
   * 返回 true 表示这次观测触发了重新锚定（调试与自测用）。
   */
  observe(reported, { duration, rate, timeline } = {}) {
    const seconds = Math.max(0, Math.floor(Number(reported) || 0))
    if (duration !== undefined) this.duration = Math.max(0, Number(duration) || 0)
    if (rate !== undefined) this.rate = Math.max(0, Number(rate) || 0)

    if (timeline !== undefined && timeline !== this.timeline) {
      this.reanchor(seconds, { timeline })
      return true
    }
    if (this.lastReported === null) {
      this.reanchor(seconds)
      return true
    }
    // 进位沿：这一秒刚跨过去 → 高质量锚点。
    if (seconds === this.lastReported + 1) {
      this.anchorMedia = seconds
      this.anchorUptime = this.now()
      this.lastReported = seconds
      this.anchoredOnEdge = true
      return true
    }
    // 非连续跳变（seek、外部换曲、长时间挂起）→ 重新锚定。
    if (seconds < this.lastReported || seconds > this.lastReported + 1) {
      this.reanchor(seconds)
      return true
    }
    // 同一整数秒：只在插值明显跑出 [reported, reported+1) 合法带时纠偏，避免每次轮询都抖一下。
    this.lastReported = seconds
    const predicted = this.read({ clampToDuration: false })
    if (predicted < seconds - 0.05 || predicted > seconds + 1.6) {
      this.anchorMedia = predicted < seconds ? seconds : seconds + 0.98
      this.anchorUptime = this.now()
      this.anchoredOnEdge = false
      return true
    }
    return false
  }

  /** 插值当前媒体时间（秒，浮点）。 */
  read({ clampToDuration = true } = {}) {
    const elapsed = Math.max(0, (this.now() - this.anchorUptime) / 1000)
    let value = this.anchorMedia + elapsed * this.rate
    if (value < 0) value = 0
    if (clampToDuration && this.duration > 0) value = Math.min(value, this.duration)
    return value
  }

  /** 0–1 进度。总时长未知时回 0。 */
  progress() {
    if (!(this.duration > 0)) return 0
    return clamp(this.read() / this.duration, 0, 1)
  }
}

function clamp(value, low, high) {
  return Math.max(low, Math.min(high, value))
}

// 显示格式（规格 §7.1）。时间一律等宽数字（CSS 侧 font-variant-numeric: tabular-nums）。

/** 时长：`m:ss`（不足 1 小时）/ `h:mm:ss`。不强制补小时位。 */
export function duration(seconds) {
  const total = Math.max(0, Math.floor(Number(seconds) || 0))
  const s = total % 60
  const m = Math.floor(total / 60) % 60
  const h = Math.floor(total / 3600)
  const two = (value) => (value < 10 ? `0${value}` : String(value))
  return h > 0 ? `${h}:${two(m)}:${two(s)}` : `${m}:${two(s)}`
}

/** 剩余时间：带 `-` 前缀；总时长 ≤ 0 时 `--:--`。 */
export function remaining(position, total) {
  if (!(Number(total) > 0)) return '--:--'
  const left = Math.max(0, Math.floor(Number(total) - Number(position)))
  return `-${duration(left)}`
}

/** 已播时间；总时长 ≤ 0 时仍显示 0:00（原生左侧始终有值）。 */
export function elapsed(position) {
  return duration(Math.max(0, Number(position) || 0))
}

export function percent(value) {
  return `${Math.round(Math.max(0, Math.min(1, Number(value) || 0)) * 100)}%`
}

/** 音效速度：`%.2f×`；预设胶囊 1.0 用 `%.0f×`，其它 `%.2g×`。 */
export function rateLabel(rate) {
  return `${(Number(rate) || 1).toFixed(2)}×`
}

export function presetRateLabel(rate) {
  const value = Number(rate) || 1
  if (Number.isInteger(value)) return `${value}×`
  return `${String(Number(value.toPrecision(2)))}×`
}

/** EQ 频段标签：< 1000 直接数字；≥ 1000 用 k。 */
export function bandLabel(hz) {
  const value = Number(hz) || 0
  return value >= 1000 ? `${value / 1000}k` : String(value)
}

/** EQ 增益：带符号整数。 */
export function gainLabel(db) {
  const value = Math.round(Number(db) || 0)
  return value > 0 ? `+${value}` : String(value)
}

/** 音质标签：仅 flac / alac 显示大写徽标；其它编码（含 Apple Music）一律不标。 */
export function losslessBadge(codec) {
  const value = String(codec || '').toLowerCase()
  return (value === 'flac' || value === 'alac') ? value.toUpperCase() : null
}

/** 曲目的稳定键：Apple Music `am:<id>`，本地/URL `url:<绝对地址>`。收藏与播放历史共用。 */
export function stableKey(track) {
  if (!track) return null
  if (track.musicItemId) return `am:${track.musicItemId}`
  if (track.url) return `url:${track.url}`
  if (track.localTrackId) return `local:${track.localTrackId}`
  return null
}

/** 「艺人 · 专辑」副标题，缺项跳过。 */
export function trackSubtitle(track) {
  return [track && track.artist, track && track.album].filter(Boolean).join(' · ')
}

/** 把工具返回的曲目对象规范成播放参数（`music_play` / `music_queue add` 都吃这套字段）。 */
export function playArgs(track) {
  const args = {}
  if (track.musicItemId) args.musicItemId = track.musicItemId
  if (track.url) args.url = track.url
  if (track.localTrackId) args.localTrackId = track.localTrackId
  if (track.title) args.title = track.title
  if (track.artist) args.artist = track.artist
  if (track.album) args.album = track.album
  if (track.artworkUrl) args.artworkUrl = track.artworkUrl
  if (Number(track.duration) > 0) args.duration = Number(track.duration)
  return args
}

// 宿主桥的薄封装。三条纪律与资讯应用一致：
//  1. 先探测再使用——能力缺席时入口整块不渲染，不留「点了没反应」的按钮；
//  2. 调用不抛到 UI 层，一律回落成可判定的返回值；
//  3. 没有 window.aibox 时（普通浏览器里预览）退化成内存实现，页面仍能跑。
//
// ⚠️ 架构裁决：播放一律遥控宿主引擎 `aibox.music.*`，**禁止** `aibox.media` 自持引擎——
// 那条路不写锁屏 NowPlaying、不注册 remote command，WebView 一挂起队列就停摆。
// 见 docs/capabilities/applet/framework-capabilities.md §3.6。

const bridge = () => (typeof window !== 'undefined' ? window.aibox : undefined)

export function hasNamespace(name, method) {
  const api = bridge()
  if (!api || !api[name]) return false
  return method ? typeof api[name][method] === 'function' : true
}

export const capabilities = {
  get music() { return hasNamespace('music', 'status') },
  get haptics() { return hasNamespace('haptics', 'impact') },
  get share() { return hasNamespace('share', 'text') },
  get openURL() { return hasNamespace('open', 'url') },
  get ui() { return hasNamespace('ui', 'confirm') },
  get tabs() { return hasNamespace('tabs', 'getState') },
  get toolbar() { return hasNamespace('toolbar', 'on') },
  get net() { return hasNamespace('net', 'fetch') },
  get storage() { return hasNamespace('storage', 'get') },
}

// MARK: - music（19 个宿主工具的一等投影）

/**
 * 调一个 `aibox.music.<method>`。统一回 `{ ok, text, json, error }`：
 * - `text` 是工具的原始文本（多数音乐工具把 JSON 直接放在 text 里，不走 details）；
 * - `json` 是 text 能解析成 JSON 时的对象/数组，否则 null；
 * - 失败不抛，`ok:false` + `error` 文本（UI 靠它反推「未授权 / 无订阅 / 真的空」）。
 */
export async function music(method, args = {}) {
  const api = bridge()
  if (!api || !api.music || typeof api.music[method] !== 'function') {
    return { ok: false, text: '', json: null, error: 'aibox/music-unavailable' }
  }
  try {
    const raw = await api.music[method](args)
    const text = String((raw && raw.text) || '')
    const ok = !(raw && (raw.ok === false || raw.isError === true))
    return { ok, text, json: parseJSON(text), details: raw && raw.details, error: ok ? null : text }
  } catch (error) {
    return { ok: false, text: '', json: null, error: String((error && error.message) || error) }
  }
}

export function parseJSON(text) {
  const trimmed = String(text || '').trim()
  if (!trimmed || (trimmed[0] !== '{' && trimmed[0] !== '[')) return null
  try {
    return JSON.parse(trimmed)
  } catch (error) {
    return null
  }
}

/**
 * 从工具的失败文案反推 Apple Music 可用性——容器没有 `music.availability()`（缺口⑨），
 * 「未授权 / 无订阅 / 真的空」三种空态在原生是分开的，这里只能按文案归类。
 */
export function classifyMusicError(text) {
  const value = String(text || '').toLowerCase()
  if (!value) return 'none'
  if (value.includes('not authorized') || value.includes('access not granted')
      || value.includes('authorization')) return 'denied'
  if (value.includes('subscription')) return 'noSubscription'
  if (value.includes('cancelled')) return 'cancelled'
  if (value.includes('not found')) return 'notFound'
  return 'error'
}

// MARK: - 触感

export const haptics = {
  impact(style = 'light') { fireAndForget('haptics', 'impact', { style }) },
  selection() { fireAndForget('haptics', 'selection', {}) },
  notify(type = 'success') { fireAndForget('haptics', 'notify', { type }) },
}

function fireAndForget(namespace, method, args) {
  const api = bridge()
  if (!api || !api[namespace] || typeof api[namespace][method] !== 'function') return
  try {
    const result = api[namespace][method](args)
    if (result && typeof result.catch === 'function') result.catch(() => {})
  } catch (error) { /* 触感失败无所谓 */ }
}

// MARK: - 原生弹层（antd-mobile 的 Toast.show 在本宿主渲染为空，命令式弹层一律走原生或自绘）

/** 二次确认。返回 true 表示用户点了确认键。宿主没有 ui 能力时保守返回 false（不误删）。 */
export async function confirm({ title, message, confirmTitle, cancelTitle, destructive = false }) {
  const api = bridge()
  if (!api || !api.ui || typeof api.ui.confirm !== 'function') return false
  try {
    const result = await api.ui.confirm({
      title,
      message,
      actions: [
        { id: 'cancel', title: cancelTitle, role: 'cancel' },
        { id: 'confirm', title: confirmTitle, role: destructive ? 'destructive' : 'default' },
      ],
    })
    return !!result && result.actionId === 'confirm' && !result.cancelled
  } catch (error) {
    return false
  }
}

/** 原生 action sheet（长按菜单）。actions = [{id,title,role}]，返回被点中的 id 或 null。 */
export async function actionSheet({ title, message, actions }) {
  const api = bridge()
  if (!api || !api.ui || typeof api.ui.actionSheet !== 'function') return null
  try {
    const result = await api.ui.actionSheet({ title, message, actions })
    if (!result || result.cancelled) return null
    return result.actionId || null
  } catch (error) {
    return null
  }
}

export async function prompt({ title, message, placeholder, defaultValue }) {
  const api = bridge()
  if (!api || !api.ui || typeof api.ui.prompt !== 'function') return null
  try {
    const result = await api.ui.prompt({ title, message, placeholder, defaultValue })
    if (!result || result.cancelled) return null
    return typeof result.value === 'string' ? result.value : null
  } catch (error) {
    return null
  }
}

// MARK: - 分享 / 打开链接

export async function shareText(text, url) {
  const api = bridge()
  if (!api || !api.share || typeof api.share.text !== 'function') return false
  try {
    await api.share.text({ text, url })
    return true
  } catch (error) {
    return false
  }
}

export async function openURL(url) {
  const api = bridge()
  if (api && api.browser && typeof api.browser.open === 'function') {
    try {
      await api.browser.open({ url, mode: 'system' })
      return true
    } catch (error) { /* 落到 open.url */ }
  }
  if (api && api.open && typeof api.open.url === 'function') {
    try {
      await api.open.url({ url })
      return true
    } catch (error) {
      return false
    }
  }
  return false
}

// MARK: - storage

const memoryStore = new Map()

export const storage = {
  async get(key) {
    const api = bridge()
    if (!api || !api.storage) return memoryStore.has(key) ? memoryStore.get(key) : null
    try {
      const value = await api.storage.get(key)
      return value === undefined ? null : value
    } catch (error) {
      return null
    }
  },
  async set(key, value) {
    const api = bridge()
    if (!api || !api.storage) { memoryStore.set(key, value); return true }
    try {
      await api.storage.set(key, value)
      return true
    } catch (error) {
      return false
    }
  },
}

// MARK: - net（只用于取封面字节）

/**
 * 取远程封面并转成 `data:` URL。
 * 为什么不能直接 `<img src="https://…">`：secure 模式的 CSP 是
 * `img-src applet: data: blob:`，远程 URL 会被整条拦掉（资讯应用也踩过，见其 imageBlocked 文案）。
 * 走原生代理拿 base64 → data URL，既过 CSP，也让 canvas 取色不被跨域污染。
 */
export async function fetchImageDataURL(url, { maxBytes = 400000 } = {}) {
  const api = bridge()
  if (!api || !api.net || typeof api.net.fetch !== 'function') return null
  if (!/^https?:\/\//i.test(String(url || ''))) return null
  try {
    const response = await api.net.fetch(url, { method: 'GET', responseType: 'base64', maxBytes })
    const status = Number((response && response.status) || 0)
    const body = String((response && response.body) || '')
    if (status < 200 || status >= 300 || !body) return null
    const mime = String((response && response.contentType) || 'image/jpeg').split(';')[0].trim()
    return `data:${mime || 'image/jpeg'};base64,${body}`
  } catch (error) {
    return null
  }
}

