// 歌词：取词 → 行模型 → 逐行同步接口。
//
// ⚠️ 当前平台事实（framework-capabilities.md §3.6.1 缺口 #2）：
// `music_lyrics` 返回的是**剥掉 `[mm:ss]` 时间轴的纯文本**（包内 `lyrics.lines.map(\.text)`），
// 所以今天只能整块居中显示 —— 当前行高亮、自动滚动、卡拉OK扫光、点行跳转**全部做不了**。
//
// 但接口按规格 §4.7 的形状**留好了**：行模型统一是 `{time, text, translation}`，
// `currentLineIndex` / `sweepRatio` 已实现且有单测。等宿主补上
// `{synced, source, lines:[{time,text,translation}]}`，只要 `readLyricsPayload` 认出结构化字段，
// 上层渲染无需改动就会自动变成逐行同步。
//
// 另外：**不要自己去网上抓歌词**。包内已有 lrclib → 网易云 → QQ 的多源链路 + 严格匹配门
// + 正负缓存 + AI 翻译，重造一份既错又会显示错歌词。

const TIME_TAG = /\[(\d{1,3}):(\d{1,2})(?:[.:](\d{1,3}))?\]/g
const OFFSET_TAG = /\[offset:\s*([+-]?\d+)\s*\]/i

/** LRC 解析（规格 §4.2）：一行多标签各产一行；`[offset:±ms]` 加到所有时间轴上；按时间升序。 */
export function parseLRC(raw) {
  const source = String(raw || '')
  if (!source) return []
  const offsetMatch = OFFSET_TAG.exec(source)
  const offset = offsetMatch ? Number(offsetMatch[1]) / 1000 : 0
  const out = []
  source.split(/\r?\n/).forEach((line) => {
    TIME_TAG.lastIndex = 0
    const times = []
    let match = TIME_TAG.exec(line)
    while (match !== null) {
      const fraction = match[3] ? Number(`0.${match[3]}`) : 0
      times.push(Number(match[1]) * 60 + Number(match[2]) + fraction)
      match = TIME_TAG.exec(line)
    }
    if (times.length === 0) return
    const text = line.replace(TIME_TAG, '').trim()
    times.forEach((time) => out.push({ time: Math.max(0, time + offset), text, translation: null }))
  })
  return out.sort((a, b) => a.time - b.time)
}

/** 纯文本歌词 → 行模型：按行拆、trim、去空行，`time = null`。 */
export function plainLines(raw) {
  return String(raw || '')
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line.length > 0)
    .map((text) => ({ time: null, text, translation: null }))
}

/** 当前行 = 最后一个满足 `time <= 显示时间 + 0.05` 的行。无时间轴时恒为 -1。 */
export function currentLineIndex(lines, displayTime) {
  if (!Array.isArray(lines) || lines.length === 0) return -1
  const threshold = Number(displayTime) + 0.05
  let found = -1
  for (let i = 0; i < lines.length; i += 1) {
    const time = lines[i].time
    if (time === null || time === undefined) continue
    if (time <= threshold) found = i
    else break
  }
  return found
}

/**
 * 当前行的卡拉OK扫光比例（规格 §4.7）：
 * `clamp((显示时间 - 本行时间) / max(0.25, 下一行时间 - 本行时间), 0, 1)`；无下一行按 +4s 估算。
 * 量化到 1/60 档，吃掉浮点微抖。
 */
export function sweepRatio(lines, index, displayTime) {
  if (!Array.isArray(lines) || index < 0 || index >= lines.length) return 0
  const line = lines[index]
  if (line.time === null || line.time === undefined) return 0
  const next = lines[index + 1]
  const end = (next && next.time !== null && next.time !== undefined) ? next.time : line.time + 4
  const span = Math.max(0.25, end - line.time)
  const raw = (Number(displayTime) - line.time) / span
  const clamped = Math.max(0, Math.min(1, raw))
  return Math.round(clamped * 60) / 60
}

const HEADER = /^Lyrics for [\s\S]*?:\n\n/
const NO_LYRICS = /^No lyrics found for/i
const NOTHING_PLAYING = /^No song specified/i

/**
 * 把 `music_lyrics` 的返回读成行模型。
 * 三条路径，按可用性从高到低：
 *  1. 宿主已经透出结构化 `lines`（未来补上缺口 #2 后）→ 直接用，`synced` 由宿主给；
 *  2. 文本里带 `[mm:ss]` → 按 LRC 解析（宿主某天改成回传原始 LRC 也能直接吃）；
 *  3. 当前实现：纯文本 → 无时间轴行模型。
 */
export function readLyricsPayload(result) {
  if (!result || !result.ok) {
    return { state: 'none', synced: false, lines: [], source: null }
  }
  const structured = result.json && !Array.isArray(result.json) ? result.json : null
  if (structured && Array.isArray(structured.lines)) {
    const lines = structured.lines
      .map((row) => ({
        time: (row && typeof row.time === 'number') ? row.time : null,
        text: String((row && row.text) || ''),
        translation: (row && row.translation) ? String(row.translation) : null,
      }))
    return {
      state: lines.length > 0 ? 'ok' : 'none',
      synced: !!structured.synced && lines.some((row) => row.time !== null),
      lines,
      source: structured.source || null,
    }
  }

  const text = String(result.text || '')
  if (!text || NO_LYRICS.test(text) || NOTHING_PLAYING.test(text)) {
    return { state: 'none', synced: false, lines: [], source: null }
  }
  const body = text.replace(HEADER, '')
  const hasTimeline = /\[\d{1,3}:\d{1,2}/.test(body)
  const lines = hasTimeline ? parseLRC(body) : plainLines(body)
  return {
    state: lines.length > 0 ? 'ok' : 'none',
    synced: hasTimeline && lines.some((row) => row.time !== null),
    lines,
    source: null,
  }
}

/** 取当前播放曲（或指定曲）的歌词。 */
export async function fetchLyrics(music, track) {
  const args = {}
  if (track && track.title) {
    args.title = track.title
    if (track.artist) args.artist = track.artist
  }
  const result = await music('lyrics', args)
  return readLyricsPayload(result)
}

// 播放控制器：唯一与宿主播放引擎对话的地方。
//
// 架构裁决（framework-capabilities.md §3.6）：**遥控 `aibox.music.*`，绝不自持引擎**。
// 播放仍由原生 AudioPlayerService 执行 → 锁屏卡片、remote command、耳机线控、后台续播、
// 中断恢复、系统音量全部由原生维护，本应用挂起也不影响。
//
// 实时面的缺口（缺口 #1）在这里被吸收：
//  · 轮询 `status`（1Hz 播放中 / 0.4Hz 暂停 / 页面不可见时停轮询）
//  · 整数秒 → SmoothClock 插值（clock.js）
//  · 队列改动先本地乐观推演（queue.js），再用 `music_queue list` 对账

import { music as callMusic, classifyMusicError, haptics } from './host.js'
import { SmoothClock } from './clock.js'
import { playArgs } from './format.js'
import * as Q from './queue.js'

const POLL_PLAYING = 1000
const POLL_IDLE = 2500
const SCRUB_HOLD_MS = 300

const EMPTY_STATUS = {
  isPlaying: false,
  playbackState: 'idle',
  currentTime: 0,
  duration: 0,
  volume: 0.5,
  repeatMode: 'off',
  isShuffled: false,
  queueCount: 0,
  currentIndex: -1,
  currentTrack: null,
  lastError: null,
}

export class MusicController {
  constructor({ store }) {
    this.store = store
    this.status = { ...EMPTY_STATUS }
    this.clock = new SmoothClock()
    this.queue = Q.emptyQueue()
    this.listeners = new Set()
    this.timer = null
    this.polling = false
    this.visible = true
    this.trackKey = null
    this.timeline = 0
    this.scrub = null
    // 松手后 0.3 秒内锁定显示的位置（防 seek 生效前回跳闪烁）；两者必须成对初始化。
    this.scrubHoldUntil = 0
    this.heldTime = 0
    this.availability = 'unknown'
    this.sleepTimer = { active: false, text: null }
    this.effects = null
    this.queueRevision = 0
    this.pendingOptimistic = null
    this.version = 0
  }

  subscribe(listener) {
    this.listeners.add(listener)
    return () => this.listeners.delete(listener)
  }

  notify() {
    this.version += 1
    this.listeners.forEach((listener) => listener())
  }

  // MARK: - 轮询

  start() {
    if (this.timer) return
    this.tick(true)
  }

  stop() {
    if (this.timer) { clearTimeout(this.timer); this.timer = null }
  }

  /** 页面不可见时停轮询：锁屏 / 后台的媒体 UI 是**原生那一面**，与本页无关，停掉纯赚。 */
  setVisible(visible) {
    const changed = this.visible !== visible
    this.visible = visible
    if (!visible) { this.stop(); return }
    if (changed) this.tick(true)
  }

  schedule() {
    if (!this.visible) return
    this.stop()
    const interval = this.status.playbackState === 'playing' ? POLL_PLAYING : POLL_IDLE
    this.timer = setTimeout(() => this.tick(false), interval)
  }

  async tick(immediate) {
    if (this.polling) return
    this.polling = true
    try {
      await this.refreshStatus()
    } finally {
      this.polling = false
      this.schedule()
    }
    if (immediate) this.notify()
  }

  async refreshStatus() {
    const result = await callMusic('status', {})
    if (!result.ok || !result.json) {
      if (result.error && result.error !== 'aibox/music-unavailable') {
        this.availability = classifyMusicError(result.error)
      }
      return
    }
    const next = { ...EMPTY_STATUS, ...result.json }
    const key = trackIdentity(next.currentTrack)
    const trackChanged = key !== this.trackKey
    const stateChanged = next.playbackState !== this.status.playbackState
      || next.isPlaying !== this.status.isPlaying
    if (trackChanged) {
      this.trackKey = key
      this.timeline += 1
      this.pendingOptimistic = null
      if (next.currentTrack) {
        this.store.recordPlay(next.currentTrack)
        this.store.setRestorePoint(next.currentTrack, next.currentTime)
      }
    }
    const rate = SmoothClock.effectiveRate({
      playbackState: next.playbackState,
      isPlaying: next.isPlaying,
      effectsRate: this.effects ? this.effects.rate : 1,
      appliesEffects: !!(this.effects && this.effects.enabled && this.effects.appliesToCurrentTrack),
    })
    this.clock.observe(next.currentTime, {
      duration: next.duration,
      rate,
      timeline: this.timeline,
    })
    const queueCountChanged = next.queueCount !== this.status.queueCount
    this.status = next
    if (next.currentTrack && !trackChanged) {
      this.store.setRestorePoint(next.currentTrack, next.currentTime)
    }
    if (queueCountChanged || trackChanged) this.refreshQueue()
    if (trackChanged || stateChanged || queueCountChanged) this.notify()
  }

  // MARK: - 读

  get currentTrack() { return this.status.currentTrack }

  get isBusy() {
    return this.status.playbackState === 'loading' || this.status.playbackState === 'buffering'
  }

  /** 显示用的播放位置：拖动中/松手 0.3s 内锁在松手位置，其余时候用插值时钟。 */
  displayTime() {
    if (this.scrub !== null) return this.scrub * (this.status.duration || 0)
    if (this.scrubHoldUntil > Date.now()) return this.heldTime
    return this.clock.read()
  }

  displayProgress() {
    if (this.scrub !== null) return this.scrub
    const total = this.status.duration || 0
    if (!(total > 0)) return 0
    return Math.max(0, Math.min(1, this.displayTime() / total))
  }

  // MARK: - 走带

  async play(track, queueTracks) {
    if (!track) return
    haptics.impact('medium')
    // 乐观点亮：不等授权 / 订阅 / 取曲 / 起播这几趟往返，先把 UI 切成播放态。
    this.pendingOptimistic = { track: playArgs(track), at: Date.now() }
    this.status = {
      ...this.status,
      isPlaying: true,
      playbackState: 'loading',
      currentTrack: playArgs(track),
      currentTime: 0,
      duration: Number(track.duration) || 0,
    }
    this.trackKey = trackIdentity(this.status.currentTrack)
    this.timeline += 1
    this.clock.reanchor(0, { duration: this.status.duration, rate: 0, timeline: this.timeline })
    this.notify()

    const args = playArgs(track)
    if (Array.isArray(queueTracks) && queueTracks.length > 0) {
      args.queue = queueTracks.map(playArgs)
    }
    const result = await callMusic('play', args)
    if (!result.ok) {
      // 失败分支如实纠回，绝不留个假的「正在播放」。
      this.status = { ...this.status, isPlaying: false, playbackState: 'failed', lastError: result.error }
      this.availability = classifyMusicError(result.error)
      this.notify()
      return
    }
    this.store.rememberArtwork(track)
    await this.refreshStatus()
    this.notify()
  }

  async transport(action) {
    if (action === 'previous' && this.displayTime() > 3) {
      // 与原生同义：> 3 秒时「上一曲」是回到本曲开头。本地先归零，视觉不等一趟往返。
      this.clock.reanchor(0, { timeline: ++this.timeline })
      this.notify()
    }
    if (action === 'pause' || action === 'resume') {
      const playing = action === 'resume'
      this.status = {
        ...this.status,
        isPlaying: playing,
        playbackState: playing ? 'playing' : 'paused',
      }
      this.clock.rate = playing ? 1 : 0
      this.clock.reanchor(this.clock.read(), { timeline: this.timeline })
      this.notify()
    }
    const result = await callMusic('transport', { action })
    if (!result.ok) this.status = { ...this.status, lastError: result.error }
    await this.refreshStatus()
    this.notify()
  }

  async togglePlayPause() {
    haptics.impact('light')
    await this.transport(this.status.isPlaying ? 'pause' : 'resume')
  }

  async retry() {
    const track = this.status.currentTrack
    if (!track) return
    await this.play(track, this.queue.tracks)
  }

  // MARK: - 进度条

  beginScrub(ratio) {
    this.scrub = clamp01(ratio)
    this.notify()
  }

  updateScrub(ratio) {
    if (this.scrub === null) return
    this.scrub = clamp01(ratio)
    this.notify()
  }

  /** 松手：锁定到松手位置 → 触感 → seek → 0.3 秒后才把控制权交还真实播放时间。 */
  async endScrub() {
    if (this.scrub === null) return
    const ratio = this.scrub
    const total = this.status.duration || 0
    const seconds = Math.round(ratio * total)
    this.heldTime = seconds
    this.scrubHoldUntil = Date.now() + SCRUB_HOLD_MS
    this.scrub = null
    haptics.selection()
    this.clock.reanchor(seconds, { timeline: ++this.timeline })
    this.notify()
    await callMusic('seek', { seconds })
    setTimeout(() => { this.refreshStatus().then(() => this.notify()) }, SCRUB_HOLD_MS)
  }

  async seekTo(seconds) {
    this.clock.reanchor(seconds, { timeline: ++this.timeline })
    this.notify()
    await callMusic('seek', { seconds: Math.max(0, Math.round(seconds)) })
  }

  // MARK: - 模式

  async setRepeat(mode) {
    this.status = { ...this.status, repeatMode: mode }
    this.notify()
    await callMusic('repeat', { mode })
    await this.refreshStatus()
    this.notify()
  }

  cycleRepeat() {
    const order = { off: 'all', all: 'one', one: 'off' }
    return this.setRepeat(order[this.status.repeatMode] || 'all')
  }

  async setShuffle(enabled) {
    this.status = { ...this.status, isShuffled: enabled }
    this.queue = Q.setShuffle(this.queue, enabled)
    this.notify()
    await callMusic('shuffle', { enabled })
    await this.refreshStatus()
    this.notify()
  }

  async setVolume(level) {
    const value = clamp01(level)
    this.status = { ...this.status, volume: value }
    this.notify()
    await callMusic('volume', { level: value })
  }

  // MARK: - 队列（权威在原生，本地只做乐观推演 + 对账）

  async refreshQueue() {
    const result = await callMusic('queue', { action: 'list' })
    const rows = Array.isArray(result.json) ? result.json : []
    this.queue = Q.reconcile(this.queue, rows)
    this.queueRevision += 1
    this.notify()
  }

  async addToQueue(tracks, at = null) {
    const list = (Array.isArray(tracks) ? tracks : [tracks]).filter(Boolean)
    if (list.length === 0) return
    haptics.impact('light')
    const before = this.queue
    this.queue = Q.add(this.queue, list.map((track) => ({ ...playArgs(track), id: localID() })), at)
    this.queueRevision += 1
    this.notify()
    const args = { action: 'add', tracks: list.map(playArgs) }
    if (at !== null && at !== undefined) args.insertAt = at
    const result = await callMusic('queue', args)
    if (!result.ok) { this.queue = before; this.notify() }
    await this.refreshQueue()
  }

  async removeFromQueue(index) {
    const before = this.queue
    const next = Q.remove(this.queue, index)
    this.queue = next
    this.queueRevision += 1
    this.notify()
    const result = await callMusic('queue', { action: 'remove', index })
    if (!result.ok) { this.queue = before; this.notify() }
    if (next.shouldStop) await callMusic('transport', { action: 'stop' })
    await this.refreshQueue()
    await this.refreshStatus()
  }

  async moveInQueue(from, to) {
    if (from === to) return
    const before = this.queue
    this.queue = Q.move(this.queue, from, to)
    this.queueRevision += 1
    this.notify()
    const result = await callMusic('queue', { action: 'move', from, to })
    if (!result.ok) { this.queue = before; this.notify() }
    await this.refreshQueue()
  }

  async clearQueue() {
    this.queue = Q.emptyQueue()
    this.queueRevision += 1
    this.notify()
    await callMusic('queue', { action: 'clear' })
    await this.refreshStatus()
    this.notify()
  }

  // MARK: - 睡眠定时器

  async refreshSleepTimer() {
    const result = await callMusic('sleepTimer', { action: 'status' })
    const text = String(result.text || '')
    this.sleepTimer = {
      active: !/^No sleep timer/i.test(text) && result.ok,
      endOfTrack: /end of current song/i.test(text),
      remaining: parseRemaining(text),
      text,
    }
    this.notify()
  }

  async setSleepTimer(minutes) {
    await callMusic('sleepTimer', { action: 'set', minutes })
    await this.refreshSleepTimer()
  }

  async setSleepTimerEndOfTrack() {
    await callMusic('sleepTimer', { action: 'end_of_track' })
    await this.refreshSleepTimer()
  }

  async cancelSleepTimer() {
    await callMusic('sleepTimer', { action: 'cancel' })
    await this.refreshSleepTimer()
  }

  // MARK: - 音效

  async refreshEffects() {
    const result = await callMusic('effects', { action: 'status' })
    if (result.json) { this.effects = result.json; this.notify() }
  }

  async updateEffects(action, args) {
    const result = await callMusic('effects', { action, ...args })
    if (result.json) this.effects = result.json
    this.notify()
  }
}

function trackIdentity(track) {
  if (!track) return null
  return String(track.musicItemId || track.url || track.id || track.title || '')
}

function clamp01(value) {
  return Math.max(0, Math.min(1, Number(value) || 0))
}

let counter = 0
function localID() {
  counter += 1
  return `local-${counter}-${Date.now()}`
}

/** 「Sleep timer: 12m 30s remaining.」→ 秒。解析不出回 null。 */
export function parseRemaining(text) {
  const match = /(\d+)m\s*(\d+)s/i.exec(String(text || ''))
  if (!match) return null
  return Number(match[1]) * 60 + Number(match[2])
}

// 队列状态机 —— 规格 §5.4 的逐条复刻（纯函数，无宿主依赖，可在 Node 里断言）。
//
// ⚠️ 权威队列在原生侧（`aibox.music.queue`）。本模块**不是影子队列**：
// 它只做两件事——
//   1. 乐观更新：拖拽排序 / 滑动删除时先本地推演出结果，UI 立刻响应，
//      随后用 `music_queue action=list` 的真值对账（`reconcile`），失败即回滚；
//   2. 顺序语义的单一表述：随机序按曲目 id 保存（不是索引）、增删移动后自动对账，
//      与原生同一套规则，便于用 Node 断言把「播放顺序乱掉」这类静默错误钉死。
//
// 跨 App 重启恢复与锁屏控制依赖的仍是原生那一份，本模块从不落盘。

/** 队列初值。tracks 里每一项至少要有 `id`。 */
export function emptyQueue() {
  return { tracks: [], currentIndex: 0, shuffledTrackIDs: [] }
}

function clamp(value, low, high) {
  return Math.max(low, Math.min(high, value))
}

/** 确定性洗牌（Fisher-Yates）。rng 可注入，测试里用固定序列。 */
export function shuffleIDs(ids, rng = Math.random) {
  const out = ids.slice()
  for (let i = out.length - 1; i > 0; i -= 1) {
    const j = Math.floor(rng() * (i + 1))
    const swap = out[i]
    out[i] = out[j]
    out[j] = swap
  }
  return out
}

/**
 * 随机序对账：剔除已不在队列里的 id，把新出现的 id 打散后追加。
 * 「打散追加」而不是「整序重建」——已播过的随机顺序不该因为加了一首歌就重排。
 */
export function reconcileShuffle(state, rng = Math.random) {
  const live = new Set(state.tracks.map((track) => track.id))
  const kept = (state.shuffledTrackIDs || []).filter((id) => live.has(id))
  const known = new Set(kept)
  const fresh = state.tracks.map((track) => track.id).filter((id) => !known.has(id))
  return { ...state, shuffledTrackIDs: fresh.length > 0 ? kept.concat(shuffleIDs(fresh, rng)) : kept }
}

/** 重建随机序；`pinCurrent` 时把当前曲提到首位（开启随机的语义）。 */
export function rebuildShuffle(state, { pinCurrent = false, rng = Math.random } = {}) {
  const ids = state.tracks.map((track) => track.id)
  let order = shuffleIDs(ids, rng)
  const current = state.tracks[state.currentIndex]
  if (pinCurrent && current) {
    order = [current.id].concat(order.filter((id) => id !== current.id))
  }
  return { ...state, shuffledTrackIDs: order }
}

/** 整体替换队列。指定曲存在则选中它，否则夹住旧下标；空队列回 0。 */
export function replace(state, tracks, currentTrackID = null, rng = Math.random) {
  const list = tracks.slice()
  let index = 0
  if (list.length > 0) {
    const found = currentTrackID ? list.findIndex((track) => track.id === currentTrackID) : -1
    index = found >= 0 ? found : clamp(state.currentIndex, 0, list.length - 1)
  }
  return rebuildShuffle({ ...state, tracks: list, currentIndex: index }, { rng })
}

/** 已在队列里就选中它；否则追加到队尾并选中。 */
export function appendOrSelect(state, track, rng = Math.random) {
  const found = state.tracks.findIndex((row) => row.id === track.id)
  if (found >= 0) return { ...state, currentIndex: found }
  const tracks = state.tracks.concat([track])
  return reconcileShuffle({ ...state, tracks, currentIndex: tracks.length - 1 }, rng)
}

/** 插入若干曲目。插入点 ≤ 当前索引时当前曲整体后移，保证「正在播的还是那一首」。 */
export function add(state, tracks, at = null, rng = Math.random) {
  if (tracks.length === 0) return state
  const insertAt = clamp(at === null || at === undefined ? state.tracks.length : at, 0, state.tracks.length)
  const next = state.tracks.slice()
  next.splice(insertAt, 0, ...tracks)
  const currentIndex = state.tracks.length === 0
    ? 0
    : (state.currentIndex >= insertAt ? state.currentIndex + tracks.length : state.currentIndex)
  return reconcileShuffle({ ...state, tracks: next, currentIndex }, rng)
}

/**
 * 删除一项。
 * - 删的位置在当前之前 → 当前索引 -1（还是同一首）
 * - 删的就是当前 → 当前 = min(原下标, 新长度-1)（顺位接上下一首）
 * - 删空 → 索引 0，并要求调用方停止播放（`shouldStop`）
 */
export function remove(state, at, rng = Math.random) {
  if (at < 0 || at >= state.tracks.length) return { ...state, shouldStop: false }
  const tracks = state.tracks.slice()
  tracks.splice(at, 1)
  let currentIndex = state.currentIndex
  if (tracks.length === 0) currentIndex = 0
  else if (at < state.currentIndex) currentIndex = state.currentIndex - 1
  else if (at === state.currentIndex) currentIndex = clamp(state.currentIndex, 0, tracks.length - 1)
  const next = reconcileShuffle({ ...state, tracks, currentIndex }, rng)
  return { ...next, shouldStop: tracks.length === 0 }
}

/** 移动一项。移动后**按 id 找回**当前曲的新下标——用下标推演在多段偏移下必错。 */
export function move(state, from, to, rng = Math.random) {
  if (from < 0 || from >= state.tracks.length) return state
  const destination = clamp(to, 0, state.tracks.length - 1)
  const currentID = state.tracks[state.currentIndex] ? state.tracks[state.currentIndex].id : null
  const tracks = state.tracks.slice()
  const [moved] = tracks.splice(from, 1)
  tracks.splice(destination, 0, moved)
  const found = currentID ? tracks.findIndex((track) => track.id === currentID) : -1
  return reconcileShuffle({ ...state, tracks, currentIndex: found >= 0 ? found : 0 }, rng)
}

/** 开启随机：重建随机序并把当前曲提到首位。关闭随机：清空随机序。 */
export function setShuffle(state, enabled, rng = Math.random) {
  if (!enabled) return { ...state, shuffledTrackIDs: [] }
  return rebuildShuffle(state, { pinCurrent: true, rng })
}

function shuffleCursor(state) {
  const current = state.tracks[state.currentIndex]
  if (!current) return -1
  return state.shuffledTrackIDs.indexOf(current.id)
}

function indexOfID(state, id) {
  return state.tracks.findIndex((track) => track.id === id)
}

/**
 * 下一首的队列下标。
 * - 随机：在随机序里前进一步；到头且 repeat=all 环回，否则 null
 * - 顺序：index + 1；越界且 repeat=all 回绕，否则 null
 * - repeat=one 不在这里处理（曲终逻辑是 seek 0 + resume，不换曲）
 */
export function nextIndex(state, { shuffled = false, repeatMode = 'off' } = {}) {
  const count = state.tracks.length
  if (count === 0) return null
  if (shuffled && state.shuffledTrackIDs.length > 0) {
    const cursor = shuffleCursor(state)
    if (cursor < 0) return indexOfID(state, state.shuffledTrackIDs[0])
    if (cursor + 1 < state.shuffledTrackIDs.length) return indexOfID(state, state.shuffledTrackIDs[cursor + 1])
    return repeatMode === 'all' ? indexOfID(state, state.shuffledTrackIDs[0]) : null
  }
  if (state.currentIndex + 1 < count) return state.currentIndex + 1
  return repeatMode === 'all' ? 0 : null
}

/** 上一首的队列下标。语义与 nextIndex 对称（`currentTime > 3` 的「回到开头」在播放层处理）。 */
export function previousIndex(state, { shuffled = false, repeatMode = 'off' } = {}) {
  const count = state.tracks.length
  if (count === 0) return null
  if (shuffled && state.shuffledTrackIDs.length > 0) {
    const cursor = shuffleCursor(state)
    if (cursor < 0) return indexOfID(state, state.shuffledTrackIDs[0])
    if (cursor - 1 >= 0) return indexOfID(state, state.shuffledTrackIDs[cursor - 1])
    return repeatMode === 'all'
      ? indexOfID(state, state.shuffledTrackIDs[state.shuffledTrackIDs.length - 1])
      : null
  }
  if (state.currentIndex - 1 >= 0) return state.currentIndex - 1
  return repeatMode === 'all' ? count - 1 : null
}

/**
 * 用原生真值对账本地投影。原生 `music_queue list` 返回 `[{...track, index, isCurrent}]`。
 * 队列身份不同（原生每次可能重新生成 UUID）时以原生为准，随机序按 id 交集保留。
 */
export function reconcile(state, nativeRows, rng = Math.random) {
  const tracks = nativeRows.map((row) => ({ ...row, id: String(row.id) }))
  const currentRow = nativeRows.findIndex((row) => row.isCurrent)
  const currentIndex = currentRow >= 0 ? currentRow : clamp(state.currentIndex, 0, Math.max(0, tracks.length - 1))
  return reconcileShuffle({ ...state, tracks, currentIndex }, rng)
}

// 本应用自己的持久化（`aibox.storage`）。
//
// 边界很重要：**播放队列不在这里**——它是原生的（跨 App 重启恢复 + 锁屏控制都依赖那一份），
// 自己再存一份会和 `music_queue` 打架。这里只存宿主 19 个工具**没有**投影出来的东西：
//  · 播放历史（原生存在偏好里，没有任何工具能读 → 队列页「最常播放」与播放历史页只能靠本地记）
//  · 搜索历史（同上，`music_search` 不带历史读写）
//  · UI 恢复点（选中 tab、上次播放曲目与位置）
//  · 封面 URL 映射（`music_status.currentTrack` 不带 artworkUrl，见 README 差异 ⑤）

import { stableKey, playArgs } from './format.js'
import { storage } from './host.js'

const KEYS = {
  ui: 'music.uiState',
  history: 'music.playHistory',
  search: 'music.searchHistory',
  artwork: 'music.artworkMap',
  prefs: 'music.prefs',
}

const LIMITS = {
  history: 500,
  recentQueries: 10,
  recentTracks: 15,
  artwork: 400,
}

export class MusicStore {
  constructor() {
    this.ui = { selectedTab: 'player', lastTrack: null, lastPosition: 0 }
    this.history = []
    this.search = { queries: [], tracks: [] }
    this.artwork = {}
    this.prefs = { autoDownloadLyrics: true, translateLang: null }
    this.version = 0
    this.listeners = new Set()
    this.loaded = false
    this.flushTimer = null
    this.dirty = new Set()
  }

  subscribe(listener) {
    this.listeners.add(listener)
    return () => this.listeners.delete(listener)
  }

  notify() {
    this.version += 1
    this.listeners.forEach((listener) => listener())
  }

  async load() {
    const [ui, history, search, artwork, prefs] = await Promise.all([
      storage.get(KEYS.ui), storage.get(KEYS.history), storage.get(KEYS.search),
      storage.get(KEYS.artwork), storage.get(KEYS.prefs),
    ])
    if (ui && typeof ui === 'object') this.ui = { ...this.ui, ...ui }
    if (Array.isArray(history)) this.history = history.filter((row) => row && row.track)
    if (search && typeof search === 'object') {
      this.search = {
        queries: Array.isArray(search.queries) ? search.queries.slice(0, LIMITS.recentQueries) : [],
        tracks: Array.isArray(search.tracks) ? search.tracks.slice(0, LIMITS.recentTracks) : [],
      }
    }
    if (artwork && typeof artwork === 'object') this.artwork = artwork
    if (prefs && typeof prefs === 'object') this.prefs = { ...this.prefs, ...prefs }
    this.loaded = true
    this.notify()
  }

  /** 合并写盘：UI 每次点击都落盘会把桥打满，攒 600ms 一起写。 */
  schedule(key) {
    this.dirty.add(key)
    if (this.flushTimer) return
    this.flushTimer = setTimeout(() => {
      this.flushTimer = null
      const pending = [...this.dirty]
      this.dirty.clear()
      pending.forEach((name) => {
        if (name === KEYS.ui) storage.set(KEYS.ui, this.ui)
        else if (name === KEYS.history) storage.set(KEYS.history, this.history)
        else if (name === KEYS.search) storage.set(KEYS.search, this.search)
        else if (name === KEYS.artwork) storage.set(KEYS.artwork, this.artwork)
        else if (name === KEYS.prefs) storage.set(KEYS.prefs, this.prefs)
      })
    }, 600)
  }

  /** 立即落盘（进入后台时调用，别把最后一次改动丢在定时器里）。 */
  flushNow() {
    if (this.flushTimer) { clearTimeout(this.flushTimer); this.flushTimer = null }
    this.dirty.clear()
    storage.set(KEYS.ui, this.ui)
    storage.set(KEYS.history, this.history)
    storage.set(KEYS.search, this.search)
    storage.set(KEYS.artwork, this.artwork)
    storage.set(KEYS.prefs, this.prefs)
  }

  // MARK: - UI 恢复点

  setSelectedTab(tab) {
    if (this.ui.selectedTab === tab) return
    this.ui.selectedTab = tab
    this.schedule(KEYS.ui)
  }

  /** 记录「上次听到哪」。position 用整数秒即可——宿主本来就只给整数。 */
  setRestorePoint(track, position) {
    if (!track) return
    this.ui.lastTrack = playArgs(track)
    this.ui.lastPosition = Math.max(0, Math.floor(Number(position) || 0))
    this.schedule(KEYS.ui)
  }

  setPref(patch) {
    this.prefs = { ...this.prefs, ...patch }
    this.schedule(KEYS.prefs)
    this.notify()
  }

  // MARK: - 播放历史（上限 500，超限按「次数 → 最近」升序删最不常用的）

  recordPlay(track) {
    const key = stableKey(track)
    if (!key) return
    const now = Date.now()
    const found = this.history.findIndex((row) => row.key === key)
    if (found >= 0) {
      this.history[found] = {
        ...this.history[found],
        track: playArgs(track),
        count: (this.history[found].count || 0) + 1,
        lastPlayed: now,
      }
    } else {
      this.history.push({ key, track: playArgs(track), count: 1, lastPlayed: now })
    }
    if (this.history.length > LIMITS.history) {
      this.history.sort((a, b) => (a.count - b.count) || (a.lastPlayed - b.lastPlayed))
      this.history = this.history.slice(this.history.length - LIMITS.history)
    }
    this.schedule(KEYS.history)
    this.notify()
  }

  removeHistory(key) {
    this.history = this.history.filter((row) => row.key !== key)
    this.schedule(KEYS.history)
    this.notify()
  }

  clearHistory() {
    this.history = []
    this.schedule(KEYS.history)
    this.notify()
  }

  /** 最常播放：按次数降序、同次数按最近降序。 */
  mostPlayed(limit = 8, excludeKey = null) {
    return this.history
      .filter((row) => row.key !== excludeKey)
      .slice()
      .sort((a, b) => (b.count - a.count) || (b.lastPlayed - a.lastPlayed))
      .slice(0, limit)
  }

  /** 最近播放（播放历史页的「最近」分段）。 */
  recentlyPlayed(limit = 60) {
    return this.history.slice().sort((a, b) => b.lastPlayed - a.lastPlayed).slice(0, limit)
  }

  // MARK: - 搜索历史

  recordQuery(query) {
    const value = String(query || '').trim()
    if (!value) return
    this.search.queries = [value].concat(this.search.queries.filter((row) => row !== value))
      .slice(0, LIMITS.recentQueries)
    this.schedule(KEYS.search)
    this.notify()
  }

  removeQuery(query) {
    this.search.queries = this.search.queries.filter((row) => row !== query)
    this.schedule(KEYS.search)
    this.notify()
  }

  clearQueries() {
    this.search.queries = []
    this.schedule(KEYS.search)
    this.notify()
  }

  recordSearchTrack(track) {
    const key = stableKey(track)
    if (!key) return
    const row = { key, track: playArgs(track) }
    this.search.tracks = [row].concat(this.search.tracks.filter((item) => item.key !== key))
      .slice(0, LIMITS.recentTracks)
    this.schedule(KEYS.search)
    this.notify()
  }

  removeSearchTrack(key) {
    this.search.tracks = this.search.tracks.filter((row) => row.key !== key)
    this.schedule(KEYS.search)
    this.notify()
  }

  clearSearchTracks() {
    this.search.tracks = []
    this.schedule(KEYS.search)
    this.notify()
  }

  // MARK: - 封面 URL 映射

  /**
   * 任何带 artworkUrl / url 的结果（搜索 / 推荐 / 资料库 / 详情）都往这里喂一次。
   * 顺带记 Apple Music 页面链接：`music_status.currentTrack` 同样不带 externalURL，
   * 「分享」与「在 Apple Music 打开」都要靠这条旁路。
   */
  rememberArtwork(track) {
    const key = stableKey(track)
    if (!key || !track) return
    const art = track.artworkUrl || null
    const link = (typeof track.url === 'string' && /^https?:\/\//i.test(track.url)) ? track.url : null
    if (!art && !link) return
    const existing = this.artwork[key] || {}
    const next = { art: art || existing.art || null, link: link || existing.link || null }
    if (existing.art === next.art && existing.link === next.link) return
    const keys = Object.keys(this.artwork)
    if (keys.length >= LIMITS.artwork && !this.artwork[key]) delete this.artwork[keys[0]]
    this.artwork[key] = next
    this.schedule(KEYS.artwork)
  }

  entry(track) {
    const key = stableKey(track)
    return key ? (this.artwork[key] || null) : null
  }

  artworkURL(track) {
    if (track && track.artworkUrl) return track.artworkUrl
    const row = this.entry(track)
    return row ? row.art : null
  }

  /** Apple Music 页面链接（分享 / 在 Apple Music 打开）。 */
  externalURL(track) {
    const row = this.entry(track)
    return row ? row.link : null
  }
}

// 子页导航 —— 把本应用的路由栈**镜像**成宿主的系统原生页栈。
//
// 用户的原话：「在小应用里面的页面导航栈，你要用系统的，这样我才能够完整地做滑返回到
// 上一个页面，而且能实时看到上一个页面。」这件事宿主已经做完了（真 `UINavigationController`
// + 冻结像素 + 活 WebView 住栈顶，见 docs/capabilities/applet/native-navigation.md），
// 应用侧要做的只有三件：
//
//   ① manifest 声明 `presentation.subpages: true` —— 这是这条能力的 opt-in 开关；
//   ② 进子页时先 `aibox.navigation.push()` **并等顺序屏障**，再渲染新路由；
//   ③ 返回一律经 `popstate` 回来，把自己的栈**对齐到 history 深度**。
//
// 不接 ②③ 的后果不是「返回没有动画」，而是「返回手势是错的」：`history.pushState`
// 从未发生 → 宿主看到的 `webDepth` 恒为 0 → 认为在根路由 → 最左缘左滑**直接退出整个
// 小应用**，用户的子页栈无声消失。这正是真机上被抱怨的那个形状。
//
// 降级（逐点与改造前一致）：宿主不在（浏览器里调试）、形态是 card/sheet/drawer、
// 或没声明 subpages 时，这里退化成纯内存栈 + 纯 Web History，功能不变。

import React from 'react'

function hostNavigation() {
  const api = (typeof window !== 'undefined' && window.aibox) || null
  return (api && api.navigation) || null
}

/**
 * 宿主桥在 `history.state` 上维护的深度标记（`AppletHostBridge` 包装了 pushState/popstate）。
 * 返回 null = 桥不在（或这条 history 记录不是桥写的）→ 调用方回落纯内存栈。
 */
export function historyDepth() {
  try {
    const state = window.history.state
    const marked = state ? Number(state.__aiboxDepth) : NaN
    return Number.isFinite(marked) ? Math.max(0, marked) : null
  } catch (error) {
    return null
  }
}

/**
 * 进一层：先让宿主冻结**当前页**的像素，再由调用方渲染新路由。
 *
 * 顺序屏障是这里唯一的技术要点：`navigation.push()` 是纯 JS，返回的是一个**已解决的**
 * Promise，`await` 它只让出一个微任务，不足以保证宿主已经处理完 `stateChanged`（= 冻结）。
 * 紧接着 `await getState()` 才是真屏障 —— 两条消息走同一个 reply handler、宿主按 FIFO
 * 在主线程处理，`getState` 的回包到达时 `stateChanged` 必然已处理完。
 *
 * 违反屏障是**观感退化而非功能损坏**：冻结下来的会是新页面的像素，于是拖动中露出的
 * 「上一页」看着像当前页；返回本身照常工作。
 */
async function hostPush(path, title) {
  const nav = hostNavigation()
  if (!nav || typeof nav.push !== 'function') return false
  try {
    await nav.push(title ? { route: path, title } : { route: path })
  } catch (error) {
    return false
  }
  if (typeof nav.getState === 'function') {
    try { await nav.getState() } catch (error) { /* 屏障失败只影响观感 */ }
  }
  return true
}

function hostBack() {
  const nav = hostNavigation()
  if (nav && typeof nav.back === 'function') {
    try { nav.back().catch(() => {}) } catch (error) { return false }
    return true
  }
  if (typeof window !== 'undefined' && window.history) { window.history.back(); return true }
  return false
}

function hostPopToRoot() {
  const nav = hostNavigation()
  if (nav && typeof nav.popToRoot === 'function') {
    try { nav.popToRoot().catch(() => {}) } catch (error) { /* 桥拒绝：栈已在本地清空 */ }
    return
  }
  const depth = historyDepth()
  if (typeof window !== 'undefined' && window.history && depth) window.history.go(-depth)
}

/** 宿主是否真的装了原生页栈。页面据此决定要不要自绘转场（本仓四个应用都不自绘）。 */
export async function subpageTransition() {
  const nav = hostNavigation()
  if (!nav || typeof nav.getState !== 'function') return 'web'
  try {
    const state = await nav.getState()
    return (state && state.transition) || 'web'
  } catch (error) {
    return 'web'
  }
}

/**
 * 路由栈 + 宿主页栈的镜像。
 *
 * - `pathFor(route)` → `#/...`，只用于宿主诊断与 `getState().url`，页面自己不读它；
 * - `titleFor(route)` → 顶栏标题；宿主会把它记进标题栈，返回时自动还原。
 */
export function useSubpageStack(options) {
  const configRef = React.useRef(options || {})
  configRef.current = options || {}

  const [stack, setStack] = React.useState([])

  // 所有返回路径（系统手势、宿主顶栏返回键、页面自己的返回键、popToRoot）最后都落到
  // popstate。这里**对齐到深度**而不是「弹一层」——popToRoot 会一次退多层。
  React.useEffect(() => {
    const onPopState = () => {
      const depth = historyDepth()
      setStack((rows) => {
        const target = depth === null ? rows.length - 1 : depth
        const clamped = Math.max(0, Math.min(rows.length, target))
        return clamped === rows.length ? rows : rows.slice(0, clamped)
      })
    }
    window.addEventListener('popstate', onPopState)
    return () => window.removeEventListener('popstate', onPopState)
  }, [])

  const push = React.useCallback((route) => {
    const { pathFor, titleFor } = configRef.current
    const path = pathFor ? pathFor(route) : `#/${(route && route.name) || 'page'}`
    const title = titleFor ? titleFor(route) : null
    // 渲染新路由必须等屏障回来，否则冻结的是新页面的像素（见 hostPush 注释）。
    hostPush(path, title).then(() => setStack((rows) => [...rows, route]))
  }, [])

  const back = React.useCallback(() => {
    // **不乐观更新**：返回要么由宿主的原生 pop 驱动、要么由 WebKit 的 back-forward 手势
    // 驱动，两条路最后都落到 popstate。抢先 setState 会让宿主的转场演给一个空页面看。
    const depth = historyDepth()
    if (depth !== null && depth > 0 && hostBack()) return
    setStack((rows) => rows.slice(0, -1))
  }, [])

  const reset = React.useCallback(() => {
    // 切 Tab 是「整条子页栈作废」，没有转场可言：乐观清空 + 通知宿主对账（幂等）。
    const depth = historyDepth()
    if (depth) hostPopToRoot()
    setStack((rows) => (rows.length === 0 ? rows : []))
  }, [])

  return {
    stack,
    route: stack.length > 0 ? stack[stack.length - 1] : null,
    push,
    back,
    reset,
  }
}

